window.GLOSARIO = [{"id":"accesibilidad","t":"Accesibilidad","s":"Que la web que haces la pueda usar cualquiera: contraste suficiente, todo con teclado, estructura que entienda un lector de pantalla y por qué no basta un escaner.","f":11},{"id":"agentes-y-herramientas","t":"Agentes y uso de herramientas","s":"Un modelo que decide qué herramienta llamar, con qué argumentos y cuándo parar: cómo se cierra el bucle, qué se guarda en memoria y por qué se descontrola.","f":8},{"id":"airflow-dagster-prefect","t":"Airflow, Dagster y Prefect","s":"Los tres orquestadores que aparecen en las ofertas de empleo, en qué se parecen y qué forma distinta de pensar propone cada uno.","f":4},{"id":"fine-tuning-vs-rag","t":"Ajuste fino frente a RAG","s":"RAG cambia lo que el modelo lee; el ajuste fino cambia cómo se comporta. Casi siempre se empieza por RAG, y aquí se explica por qué.","f":8},{"id":"fine-tuning-y-lora","t":"Ajuste fino y LoRA","s":"Entrenar todos los pesos, solo una cabeza nueva o un par de matrices pequenas por capa: la diferencia esta en memoria, en estabilidad y en cuantos checkpoints guardas.","f":7},{"id":"aleatoriedad-y-muestreo","t":"Aleatoriedad y muestreo","s":"Generadores pseudoaleatorios, semillas, muestreo uniforme y ponderado, y los sesgos que convierten una muestra en una conclusión falsa.","f":10},{"id":"algoritmos-de-aproximacion","t":"Algoritmos de aproximación","s":"Cuando el óptimo es inalcanzable en tiempo razonable, se renuncia a él a cambio de una garantía demostrable sobre cuánto se aleja la solución.","f":10},{"id":"algoritmos-de-ejecucion","t":"Algoritmos de ejecución: VWAP, TWAP e iceberg","s":"Cómo partir una orden grande en trozos para que no la vea el mercado, y cómo cada algoritmo cambia lo que pagas por el mismo pedido.","f":9},{"id":"algoritmos-de-join","t":"Algoritmos de join","s":"Bucle anidado, hash join y sort-merge join: cuándo es viable cada uno, cómo desborda el Grace hash a disco y por qué una clave sesgada rompe el reparto.","f":10},{"id":"ordenacion","t":"Algoritmos de ordenación","s":"Ordenar es el paso previo de casi todo; quicksort, mergesort, heapsort y counting sort no son intercambiables y la cota inferior es n log n.","f":10},{"id":"algoritmos-de-streaming","t":"Algoritmos de streaming","s":"Muestrear, contar y resumir un flujo que no cabe en memoria y que solo pasa una vez, con estructuras cuyo error está acotado por contrato.","f":10},{"id":"algoritmos-greedy","t":"Algoritmos voraces","s":"Elegir en cada paso la opción que parece mejor es rapidísimo y a veces óptimo; la diferencia entre las dos cosas hay que demostrarla, no suponerla.","f":10},{"id":"almacenamiento-de-objetos","t":"Almacenamiento de objetos","s":"Un disco remoto al que se accede por HTTP con objetos enteros; el prefijo hace de carpeta, la clase decide el coste y la frecuencia de lectura decide la clase.","f":4},{"id":"alpha-y-beta","t":"Alpha y beta","s":"Beta es lo que tu estrategia se mueve con el mercado y alpha lo que queda cuando descuentas esa parte; sin el error típico, el alpha no dice nada.","f":9},{"id":"alucinaciones-y-limites","t":"Alucinaciones y límites","s":"Por qué un modelo inventa datos con total seguridad, cómo se detecta una respuesta sin apoyo en las fuentes y qué decisiones no se le deben delegar nunca.","f":8},{"id":"analisis-amortizado","t":"Análisis amortizado","s":"Repartir el coste de una secuencia entre sus operaciones: por qué añadir al final de una lista sale a O(1) aunque alguna inserción concreta cueste O(n).","f":10},{"id":"pca","t":"Análisis de componentes principales","s":"Sustituye variables correlacionadas por unas pocas direcciones que concentran la varianza, y deja claro qué información se tira al hacerlo.","f":6},{"id":"analisis-de-supervivencia","t":"Análisis de supervivencia","s":"Modelar el tiempo hasta un evento cuando muchos casos aún no lo han sufrido: función de supervivencia, Kaplan-Meier, log-rank y riesgos proporcionales.","f":5},{"id":"eda-pasos","t":"Análisis exploratorio: el método","s":"Una rutina ordenada para conocer un dataset antes de modelarlo: qué es una fila, qué falta, qué rangos son posibles, cómo se distribuye y con qué se relaciona.","f":5},{"id":"anomalias-en-series-temporales","t":"Anomalías en series temporales","s":"En una serie con deriva y ciclo, el z-score global no marca nada; hay que detectar sobre el residuo, con una escala robusta y contando los ecos.","f":5},{"id":"anova","t":"ANOVA","s":"Comparar las medias de tres o más grupos con un solo contraste, descomponiendo la variabilidad total en la de dentro y la de entre grupos.","f":2},{"id":"apis-rest","t":"APIs REST","s":"Recursos, verbos y códigos de estado bien elegidos: la API que cualquiera puede usar sin leer tu documentación entera.","f":11},{"id":"apis-y-peticiones-http","t":"APIs y peticiones HTTP","s":"Una API es una promesa por escrito con método, ruta, código de estado y formato; aquí se aprende a leerla, paginarla y reintentarla sin abusar del servidor.","f":3},{"id":"aprendizaje-activo","t":"Aprendizaje activo","s":"Elegir que filas etiquetar para aprender mas con menos anotaciones: incertidumbre, comite, diversidad y criterios de parada","f":6},{"id":"aprendizaje-por-refuerzo","t":"Aprendizaje por refuerzo","s":"Un agente actua sobre un entorno, recibe recompensas y aprende una política que maximiza el retorno acumulado a base de probar y equivocarse.","f":7},{"id":"transfer-learning","t":"Aprendizaje por transferencia","s":"Reutilizar un modelo ya entrenado en otra tarea y adaptarlo a la tuya con pocas etiquetas, en vez de empezar de cero cada vez.","f":7},{"id":"aprendizaje-semi-supervisado","t":"Aprendizaje semisupervisado","s":"Aprovechar millones de filas sin etiquetar con autosupervisión, pseudoetiquetado y propagación de etiquetas cuando anotar es caro","f":6},{"id":"arbitraje-estadistico","t":"Arbitraje estadístico","s":"Cientos de posiciones pequeñas para explotar la reversión de lo que los factores no explican, con una sensibilidad al coste que decide si existe negocio.","f":9},{"id":"arboles-balanceados","t":"Árboles balanceados","s":"AVL, rojo-negro y B-árboles garantizan altura logarítmica con reglas locales de reequilibrio, y por eso sostienen los índices de las bases de datos.","f":10},{"id":"arboles-binarios","t":"Árboles binarios y de búsqueda","s":"Jerarquías de nodos con dos hijos por nodo; ordenados como BST dan búsqueda logarítmica y, sobre todo, recorrido en orden y consultas por rango.","f":10},{"id":"arboles-de-decision","t":"Árboles de decisión","s":"Dividir los datos con preguntas binarias eligiendo el corte que más reduce la impureza: potente, interpretable y adicto al sobreajuste.","f":6},{"id":"tries","t":"Árboles de prefijos (tries)","s":"Un árbol con un carácter por arista que permite buscar, insertar y autocompletar por prefijo en tiempo proporcional a la longitud de la palabra, no al número de palabras.","f":10},{"id":"arima-sarima","t":"ARIMA y SARIMA","s":"Autorregresión, diferencias y media móvil combinadas para pronosticar una serie, con la versión estacional que repite la estructura cada s periodos.","f":5},{"id":"arquitectura-de-aplicaciones","t":"Arquitectura de aplicaciones: capas, límites y dependencias","s":"Qué puede importar a qué: la regla que evita que un cambio en la base de datos obligue a tocar la interfaz, y cómo se comprueba sin discusión.","f":11},{"id":"arquitectura-medallion","t":"Arquitectura medallion","s":"Bronce, plata y oro: tres capas con responsabilidades distintas que se reconstruyen en cadena para que la calidad del dato se pueda auditar.","f":4},{"id":"lambda-y-kappa","t":"Arquitecturas lambda y kappa","s":"Dos formas de resolver «lote y tiempo real»: lambda mantiene dos caminos que hay que reconciliar, kappa uno solo que se reprocesa desde el registro.","f":4},{"id":"arrays-y-listas","t":"Arrays y listas","s":"Un array guarda sus elementos uno detrás de otro: por eso el acceso por índice es instantáneo y por eso insertar en el medio obliga a desplazar todo lo demás.","f":10},{"id":"arrow-y-formatos-columnares","t":"Arrow y formatos columnares","s":"Guardar los datos por columnas y no por filas: menos bytes leídos, mejor compresión y una misma representación en memoria que los motores comparten sin copiar.","f":3},{"id":"asimetria-y-curtosis","t":"Asimetría y curtosis","s":"La asimetría dice hacia qué lado se estira la cola y la curtosis cuánto pesan los extremos; son los dos números que delatan que unos datos no son normales.","f":1},{"id":"autenticacion-y-autorizacion","t":"Autenticación y autorización","s":"Quien eres y qué puedes hacer: sesiones, tokens, JWT, OAuth y los errores de seguridad que se repiten en cada proyecto.","f":11},{"id":"autocorrelacion-acf-pacf","t":"Autocorrelación, ACF y PACF","s":"Cuanto se parece una serie a sí misma desplazada k pasos, y qué queda de ese parecido cuando descuentas los retardos intermedios.","f":5},{"id":"autoencoders-y-vae","t":"Autoencoders y VAE","s":"Comprimir la entrada en un cuello de botella y reconstruirla: sirve para reducir dimensión, detectar anomalías y, con un VAE, generar muestras nuevas.","f":7},{"id":"automl","t":"AutoML","s":"Busqueda automática de modelos, variables e hiperparámetros: acelera el punto de partida y no sustituye a entender el problema","f":6},{"id":"autovalores-y-autovectores","t":"Autovalores y autovectores","s":"Son las direcciones que una matriz no gira, solo estira; su autovalor dice cuánto, y de ahí salen PCA, PageRank y el análisis de estabilidad.","f":1},{"id":"probabilidad-axiomas","t":"Axiomas de probabilidad","s":"Espacio muestral, sucesos, unión e intersección: los tres axiomas de Kolmogorov y las reglas de suma que sostienen toda la estadística.","f":1},{"id":"backfill-y-reproceso","t":"Backfill y reproceso","s":"Rellenar las particiones que faltan y recalcular las que ya existen es rutina; el peligro es aplicar la lógica de hoy al pasado sin darse cuenta.","f":4},{"id":"backtesting-por-eventos","t":"Backtesting por eventos","s":"Simular el backtest orden por orden, con cola, latencia y ejecuciones parciales, para saber si tu estrategia sobrevive al mercado real.","f":9},{"id":"backtesting-vectorizado","t":"Backtesting vectorizado","s":"Calcular la posición y el resultado de toda la serie de golpe con arrays: rapidísimo para explorar ideas y muy fácil de contaminar sin que salte ningún error.","f":9},{"id":"bagging-y-random-forest","t":"Bagging y Random Forest","s":"Entrenar muchos árboles sobre muestras bootstrap y promediar: baja la varianza, y el submuestreo de variables evita que todos se equivoquen igual.","f":6},{"id":"bandits-y-decision-secuencial","t":"Bandits y decisión secuencial","s":"Decidir y aprender a la vez: epsilon-greedy, UCB y Thompson sampling reparten las pruebas entre la opción que crees mejor y las que aún no conoces.","f":6},{"id":"bases-de-datos-vectoriales","t":"Bases de datos vectoriales","s":"Índices para buscar el vecino más cercano entre millones de vectores: qué hacen HNSW e IVF, qué recall sacrifican y cómo se combina con filtros.","f":8},{"id":"bi-y-consumo","t":"BI y capa de consumo","s":"Cuadros de mando sobre tablas curadas: cuándo consultar en vivo, cuándo servir un extracto más barato y qué se publica con dueño y fecha de caducidad.","f":4},{"id":"bootstrap","t":"Bootstrap y remuestreo","s":"Remuestrear tus propios datos con reemplazo para estimar la incertidumbre de casi cualquier estadístico, sin suponer una distribución.","f":2},{"id":"numpy-broadcasting","t":"Broadcasting de NumPy","s":"NumPy estira las formas compatibles para operar arrays de tamaños distintos sin copiar datos, y por eso una resta mal alineada puede pasar desapercibida.","f":3},{"id":"busqueda-binaria","t":"Búsqueda binaria","s":"Partir el espacio de búsqueda por la mitad en cada paso convierte mil elementos en diez comparaciones, siempre que la frontera esté bien puesta.","f":10},{"id":"seleccion-de-hiperparametros","t":"Búsqueda de hiperparámetros","s":"Rejilla, búsqueda aleatoria, bayesiana y Hyperband: cómo repartir el presupuesto de entrenamientos sin sobreajustar la validación.","f":6},{"id":"cache-y-redis","t":"Caché y Redis","s":"Guardar el resultado caro para no repetirlo: qué cachear, cuándo invalidar y por qué el TTL es solo una parte del problema.","f":11},{"id":"cadenas-de-markov","t":"Cadenas de Markov","s":"Un sistema que salta entre estados sin memoria, y cómo su matriz de transición permite calcular a dónde irá y cuánto tardará en quedarse atrapado.","f":1},{"id":"hmm-regimenes","t":"Cadenas de Markov ocultas","s":"Un modelo de estados ocultos que cambian con una cadena de Markov: estima en qué régimen estas, cuanto dura y cuando es probable que cambie.","f":5},{"id":"maximo-drawdown","t":"Caída máxima (max drawdown)","s":"La mayor caída desde un pico de tu curva de capital hasta el mínimo anterior a recuperarlo: cuánto duele, cuánto dura y por qué decide si aguantas.","f":9},{"id":"tamano-muestral","t":"Cálculo de tamaño muestral","s":"Cuantas observaciones necesitas para detectar el efecto que te importa, y por qué calcularlo después de ver los datos no sirve de nada.","f":2},{"id":"calibracion","t":"Calibración de probabilidades","s":"Que un 0,7 sea de verdad un 70 por ciento: cómo se mide la calibración, cómo se arregla y por qué el AUC no la ve.","f":6},{"id":"calidad-de-datos","t":"Calidad de datos","s":"Nulos, duplicados, rangos imposibles y coherencia entre columnas convertidos en proporciones que se miden, se vigilan y se reclaman al origen.","f":3},{"id":"etiquetas-y-techo-del-modelo","t":"Calidad de las etiquetas y techo del modelo","s":"Cuánto rendimiento te está costando el ruido de las etiquetas y cómo estimar el techo real de un modelo antes de gastar otra semana entrenando.","f":6},{"id":"calidad-y-slas","t":"Calidad y acuerdos de nivel de servicio","s":"El SLI es cómo mides la calidad, el SLO el umbral que te exiges y el SLA el acuerdo con consecuencia; sin un número medible no hay promesa que valga.","f":4},{"id":"caminos-minimos","t":"Caminos mínimos","s":"Dijkstra, Bellman-Ford, Floyd-Warshall y A* resuelven el mismo problema con supuestos distintos; elegir el que no toca da respuestas seguras y equivocadas.","f":10},{"id":"cap-y-consistencia","t":"CAP y modelos de consistencia","s":"Que significan exactamente C, A y P, qué se puede y qué no cuando la red se parte, y cómo se paga la consistencia en latencia y disponibilidad.","f":11},{"id":"capa-semantica-y-metricas","t":"Capa semántica y métricas","s":"Definir cada métrica una sola vez, con su medida, su agregación, su grano y sus filtros, para que el cuadro, la API y el modelo devuelvan el mismo número.","f":4},{"id":"catalogo-y-linaje","t":"Catálogo y linaje","s":"El catálogo dice qué datos existen y de quién son; el linaje dice de dónde vienen y qué se rompe al cambiarlos, columna a columna.","f":4},{"id":"causalidad-vs-correlacion","t":"Causalidad frente a correlación","s":"Dos variables pueden moverse juntas por cuatro motivos distintos, y solo uno de ellos es que una cause a la otra; estos son los requisitos para poder decirlo.","f":2},{"id":"certificaciones-de-datos","t":"Certificaciones de datos","s":"Qué certifica cada examen de datos, en qué orden sacarlas según el mercado y cómo se prepara una sin estudiar el doble de lo que pide.","f":12},{"id":"ciclo-de-vida-del-dato","t":"Ciclo de vida del dato","s":"Todo dato recorre seis etapas, de la captura al borrado, y cada una tiene dueño, coste y plazo; lo que no se borra a tiempo acaba siendo un pasivo.","f":4},{"id":"clases-y-objetos","t":"Clases y objetos","s":"Una clase es el molde, cada objeto guarda su propio estado y self es cómo un método sabe sobre qué objeto trabaja.","f":3},{"id":"clustering-jerarquico","t":"Clustering jerárquico","s":"Construir un árbol de agrupaciones de abajo arriba, elegir el criterio de enlace y decidir el número de grupos cortando el dendrograma a la altura adecuada.","f":6},{"id":"encoding-de-categoricas","t":"Codificación de categóricas","s":"Convertir categorías en números sin inventar un orden y sin colar la variable objetivo: one-hot, ordinal, frecuencia y target encoding con su trampa.","f":5},{"id":"entrenamiento-frente-a-inferencia","t":"Coherencia entre entrenamiento e inferencia","s":"Un modelo acierta en producción solo si el dato llega transformado igual que en el entrenamiento; la mitad de los fallos son de escala, no de algoritmo.","f":6},{"id":"cointegracion","t":"Cointegración","s":"Dos series que vagan sin rumbo pero mantienen una combinación lineal estacionaria: la base estadística del trading de pares y del arbitraje estadístico.","f":9},{"id":"colas-y-mensajeria","t":"Colas y mensajería","s":"Desacoplar productor y consumidor, reintentar sin duplicar y aceptar que ordenar cuesta dinero.","f":11},{"id":"como-estudiar","t":"Cómo estudiar esto","s":"Recuperar de memoria, repartir los repasos en el tiempo e intercalar temas: eso es estudiar. Releer y subrayar solo dan sensación de aprender.","f":0},{"id":"como-funciona-un-llm","t":"Cómo funciona un LLM","s":"Un LLM solo predice el siguiente token; todo lo demas (chat, código, resumenes) es repetir esa predicción dentro de una ventana de contexto.","f":8},{"id":"como-leer-un-paper","t":"Cómo leer un paper","s":"Tres pasadas de coste creciente, saber cuándo abandonar y mirar la tabla de resultados antes que las matemáticas: leer un paper es un presupuesto.","f":0},{"id":"mapa-del-portal","t":"Cómo usar este portal","s":"Rutas, fases, prerequisitos, preguntas de repaso y exportación a Anki: cómo moverte por el temario sin perderte ni repetir lo que ya sabes.","f":0},{"id":"complejidad-asintotica","t":"Complejidad asintótica","s":"Como crece el trabajo de un algoritmo cuando crece la entrada: O, Ω y Θ sirven para comparar dos soluciones sin cronómetro y sin depender de la máquina.","f":10},{"id":"series-temporales-componentes","t":"Componentes de una serie temporal","s":"Toda serie temporal se lee como suma de una tendencia, un patrón que se repite, ciclos largos y ruido; separarlos es el primer paso para pronosticar.","f":5},{"id":"comprensiones-y-generadores","t":"Comprensiones y generadores","s":"Las comprensiones construyen listas y diccionarios en una línea; los generadores producen los valores de uno en uno y no gastan memoria aunque pidas millones.","f":3},{"id":"compresion","t":"Compresión","s":"Huffman, LZ y codificación por diccionario: cómo se quita redundancia a los datos, cuál es el límite teórico y por qué comprimir suele acelerar.","f":10},{"id":"compresion-y-codificacion","t":"Compresión y codificación","s":"Diccionarios, rachas y delta codifican los valores según su tipo; Snappy, Zstd y gzip comprimen los bytes resultantes. Menos bytes casi siempre es menos tiempo.","f":4},{"id":"sesgo-varianza","t":"Compromiso sesgo-varianza","s":"El error al predecir datos nuevos se reparte entre ruido irreducible, sesgo y varianza; la curva que explica por qué más complejo no siempre es mejor.","f":6},{"id":"concurrencia-algoritmica","t":"Concurrencia y paralelismo","s":"Varias tareas en curso a la vez: por qué dos operaciones correctas se estropean al intercalarse y qué garantiza de verdad un candado.","f":10},{"id":"concurrencia-async-hilos-procesos","t":"Concurrencia, asincronía, hilos y procesos","s":"Esperar a la red, repartir CPU y compartir memoria: qué resuelve cada modelo en Python y cuándo el GIL te deja sin nada.","f":11},{"id":"confusores-y-dag","t":"Confusores, mediadores y DAG","s":"Dibujar el grafo causal antes de tocar la regresión decide qué variables ajustar y, sobre todo, de cuáles no hay que tocar nada.","f":2},{"id":"train-val-test","t":"Conjuntos de entrenamiento, validación y prueba","s":"Tres particiones con tres papeles distintos: entrenar, decidir y medir una sola vez. Mirar el test más de la cuenta lo convierte en validación.","f":6},{"id":"union-find","t":"Conjuntos disjuntos (union-find)","s":"Mantiene una partición en grupos que se van fusionando, con dos optimizaciones que dejan cada operación en un coste prácticamente constante.","f":10},{"id":"consenso-y-replicacion","t":"Consenso y replicación","s":"Cómo un clúster se pone de acuerdo en un valor y en su orden: mayorías, términos, elección de líder y por qué un número par de nodos no aporta nada.","f":11},{"id":"construccion-de-carteras","t":"Construcción de carteras","s":"Combinar varias estrategias o activos con pesos decididos, de forma que el conjunto tenga mejor relación entre rentabilidad y riesgo que cualquiera de las partes.","f":9},{"id":"storytelling-con-datos","t":"Contar historias con datos","s":"Un análisis no convence por tener mas gráficos, sino por decir el mensaje en la primera línea, dar contexto para comparar y no ocultar lo que no sabes.","f":12},{"id":"contenedores","t":"Contenedores","s":"Un contenedor no es una máquina virtual pequeña: es un proceso normal con namespaces, límites de recursos y un sistema de ficheros montado por capas.","f":11},{"id":"contraste-de-hipotesis","t":"Contraste de hipótesis","s":"Un procedimiento que fija de antemano qué resultado contarías como prueba contra la hipótesis nula, y decide si lo observado cae ahí.","f":2},{"id":"contratos-de-datos","t":"Contratos de datos","s":"El contrato fija esquema, semántica, calidad y política de cambios entre productor y consumidor, y sólo sirve si un test lo comprueba en cada despliegue.","f":4},{"id":"open-source","t":"Contribuir a código abierto","s":"Encontrar un fallo reproducible, arreglarlo en un parche pequeño que otro pueda revisar y responder a la revisión: así se entra y se construye reputación.","f":12},{"id":"control-de-acceso-por-fila-y-columna","t":"Control de acceso por fila y por columna","s":"Que el motor recorte filas y columnas según quién consulta, para que la autorización no dependa de que cada aplicación, cuadro o notebook se acuerde de filtrar.","f":4},{"id":"convexidad","t":"Convexidad","s":"Una función convexa tiene un único valle: cualquier mínimo local es el global, y eso convierte un problema de optimización en un problema resuelto.","f":1},{"id":"copias-de-seguridad-y-recuperacion","t":"Copias de seguridad y recuperación ante desastres","s":"Cuánto dato puedes permitirte perder y cuánto tardas en volver: RPO y RTO, la regla 3-2-1, copias inmutables y la única prueba que vale, restaurar de verdad.","f":11},{"id":"correccion-point-in-time","t":"Corrección point-in-time","s":"Guardar cada dato con la fecha en que estuvo disponible y no con la del evento, la disciplina que separa un pipeline honesto de un backtest inflado.","f":4},{"id":"correlacion-pearson-spearman","t":"Correlación de Pearson y Spearman","s":"Pearson mide cuánto se pega la nube de puntos a una recta y Spearman solo el orden; un único valor atípico puede mover la primera y no la segunda.","f":1},{"id":"coste-y-latencia","t":"Coste y latencia","s":"El presupuesto de una consulta se decide con tres números (tokens de entrada, de salida y aciertos de caché) y la latencia se reparte entre el primer token y el resto.","f":8},{"id":"coste-y-optimizacion","t":"Coste y optimización","s":"En analítica se paga sobre todo por bytes leídos, bytes guardados y horas de cómputo, así que optimizar es leer menos, archivar antes y no repetir trabajo.","f":4},{"id":"covarianza-y-correlacion","t":"Covarianza y correlación","s":"Cuanto tienden dos variables a moverse juntas, la versión sin unidades de esa medida y las tres cosas que la correlación no dice.","f":1},{"id":"criterio-de-kelly","t":"Criterio de Kelly","s":"La fracción del capital que maximiza el crecimiento esperado a largo plazo: ni tan poca que desaprovechas la ventaja, ni tanta que una racha te saque de la ecuación.","f":9},{"id":"dashboards","t":"Cuadros de mando","s":"Un cuadro de mando no es una pared de gráficos, sino un puñado de métricas accionables con dueño, frecuencia de actualización y umbral de alerta.","f":12},{"id":"cuantiles-y-percentiles","t":"Cuantiles y percentiles","s":"El percentil 95 de latencia es el tiempo que solo superan 5 de cada 100 peticiones; los cuantiles resumen sin suponer ninguna forma concreta.","f":1},{"id":"cuantizacion-y-destilacion","t":"Cuantización y destilación","s":"Dos formas independientes de encoger un modelo: gastar menos bits por peso (cuantización) o entrenar una red pequeña que imite a una grande (destilación).","f":7},{"id":"curva-de-tipos-y-descuento","t":"Curva de tipos y descuento","s":"Por qué el tipo de interés depende del plazo, qué es el factor de descuento y cómo un punto de tipos mueve mucho más un bono a diez años que uno a dos.","f":9},{"id":"precision-recall-y-pr","t":"Curva precisión-exhaustividad","s":"La curva que mide lo que de verdad importa cuando el positivo es raro, con una línea base que es la prevalencia y no el 0,5.","f":6},{"id":"roc-auc","t":"Curva ROC y AUC","s":"El rastro que deja un clasificador al mover su umbral y el área bajo esa curva, con el sesgo que esconde cuando el positivo es raro.","f":6},{"id":"data-lake","t":"Data lake","s":"Guardar los datos tal como llegan, en ficheros sobre almacenamiento de objetos, y ponerles esquema y orden al leerlos: mucha potencia y mucho pantano posible.","f":4},{"id":"data-mesh","t":"Data mesh","s":"Los dominios poseen sus datos y los publican como producto sobre una plataforma self-service, con un gobierno federado que se aplica como código.","f":4},{"id":"data-snooping-y-multiple-testing","t":"Data snooping y pruebas múltiples","s":"Si pruebas muchas ideas y te quedas con la mejor, el resultado está sesgado: cuántos intentos hacen falta para que el azar parezca una estrategia rentable.","f":9},{"id":"data-warehouse","t":"Data warehouse","s":"El almacén curado donde los datos de muchos sistemas se limpian, se integran y se modelan una sola vez para que toda la empresa use las mismas cifras.","f":4},{"id":"datos-agrupados-y-errores-tipicos","t":"Datos agrupados y errores típicos","s":"Cómo calcular la media y el error típico cuando tus datos vienen ya agrupados en frecuencias, y por qué confundir grupos con observaciones infla el error por diez.","f":2},{"id":"missing-data","t":"Datos ausentes","s":"MCAR, MAR y MNAR describen por qué falta cada dato, y ese mecanismo —no el porcentaje de nulos— decide si borrar filas sesga el resultado.","f":2},{"id":"datos-de-mercado-y-acciones-corporativas","t":"Datos de mercado y acciones corporativas","s":"Un precio bruto no es comparable consigo mismo en el tiempo: splits, dividendos y cambios de horario obligan a ajustar la serie antes de calcular nada.","f":4},{"id":"tick-data-y-ohlcv","t":"Datos de transacción y velas","s":"Del tick a la vela: cada agregación resume el mercado y borra parte de la historia; saber qué se pierde evita backtests que solo funcionan en papel.","f":9},{"id":"datos-geoespaciales","t":"Datos geoespaciales","s":"Coordenadas, proyecciones y unir por cercanía en vez de por igualdad: por qué un grado de longitud no mide lo mismo en Oslo que en Dakar.","f":6},{"id":"datos-que-no-caben-en-memoria","t":"Datos que no caben en memoria","s":"Si la tabla no cabe en RAM se lee por bloques y se agrega sobre la marcha; el resultado de una agregación es diminuto aunque el fichero tenga 50 GB.","f":3},{"id":"dbscan-y-hdbscan","t":"DBSCAN y HDBSCAN","s":"Agrupar por densidad en vez de por distancia al centro: encuentra formas arbitrarias, marca el ruido y no obliga a fijar el número de grupos de antemano.","f":6},{"id":"dbt-y-transformacion","t":"dbt y transformación","s":"dbt convierte tus consultas SQL en un proyecto con dependencias, materializaciones, pruebas y documentación; el grafo lo deduce él a partir de ref().","f":4},{"id":"alpha-decay","t":"Decaimiento del alpha","s":"Toda señal pierde fuerza: cómo medir la vida media del alpha, distinguirla del sobreajuste y decidir cuándo una estrategia ha dejado de existir.","f":9},{"id":"depuracion-de-redes","t":"Depurar el entrenamiento","s":"Perdidas que no bajan, perdidas que son NaN y modelos que solo aprenden un lote: el método para aislar cada fallo con comprobaciones baratas.","f":7},{"id":"monitorizacion-de-drift","t":"Deriva de datos y de concepto","s":"Un modelo solo vale para la distribución con la que se entrenó; la deriva es el aviso de que el mundo cambió y la métrica de negocio todavía no se ha enterado.","f":4},{"id":"derivadas-parciales-y-gradiente","t":"Derivadas parciales y gradiente","s":"La derivada parcial mide como cambia una función al mover una sola variable; el gradiente las junta en un vector que apunta al maximo crecimiento.","f":1},{"id":"derivadas-y-reglas","t":"Derivadas y reglas de derivación","s":"La derivada es la pendiente de la recta tangente; las reglas de producto, cociente y cadena permiten derivar sin volver al límite cada vez.","f":1},{"id":"tdd","t":"Desarrollo guiado por pruebas","s":"Rojo, verde, refactor: escribir la prueba antes que el código convierte el diseño en una decisión consciente y el ritmo en minutos en vez de días.","f":11},{"id":"desbalanceo-de-clases","t":"Desbalanceo de clases","s":"Cuando el 1 % de los casos son positivos, el accuracy engaña; lo que hay que ajustar es la métrica, el peso de las clases y el umbral de decisión.","f":5},{"id":"descomposicion-svd","t":"Descomposición en valores singulares","s":"Cualquier matriz se escribe como giro, estirado y giro; quedarte con los valores singulares grandes comprime y limpia sin perder lo esencial.","f":1},{"id":"descomposicion-stl","t":"Descomposición STL","s":"Separa una serie en tendencia, estacionalidad y residuo con suavizados locales, y deja que el patrón estacional cambie de un ciclo a otro.","f":5},{"id":"slippage-y-comisiones","t":"Deslizamiento y comisiones","s":"Comisiones, diferencial e impacto: los tres costes que se pagan en cada operación y que convierten una estrategia ganadora en papel en una perdedora en real.","f":9},{"id":"deteccion-de-anomalias","t":"Detección de anomalías","s":"Encontrar lo raro cuando nadie te ha dicho qué es raro: puntuaciones de rareza, umbrales que son una decisión de negocio y validación con muy pocos positivos.","f":6},{"id":"determinante-rango-invertibilidad","t":"Determinante, rango e inversa","s":"El determinante mide cuánto deforma una matriz; si vale cero, sus columnas son dependientes, el rango baja y la inversa no existe.","f":1},{"id":"diagnostico-de-residuos","t":"Diagnóstico de residuos","s":"Los cuatro contrastes que se hacen después de cada ajuste (Ljung-Box, Jarque-Bera, ARCH-LM y Durbin-Watson) y cómo leer la ACF de los residuos.","f":5},{"id":"diferenciacion-fraccional","t":"Diferenciación fraccional","s":"Diferenciar con orden fraccionario hace estacionaria una serie conservando su memoria: gana el test de raíz unitaria sin perder la correlación con el pasado.","f":9},{"id":"scd-dimensiones-cambiantes","t":"Dimensiones que cambian (SCD)","s":"Como guardar la historia de un atributo que cambia sin reescribir el pasado: tipos 1, 2, 3 y 6, claves sustitutivas y fechas de validez.","f":4},{"id":"disenos-factoriales-e-interacciones","t":"Diseños factoriales e interacciones","s":"Varía varios factores a la vez para estimar cada efecto con todos los datos y para detectar la interacción, que es la mitad de la respuesta y casi siempre la pregunta.","f":2},{"id":"distribucion-normal-multivariante","t":"Distribución normal multivariante","s":"Modela varias variables que se mueven juntas cuando cada una es normal, y explica por qué la correlación cambia la probabilidad conjunta sin tocar las marginales.","f":1},{"id":"distribuciones-continuas","t":"Distribuciones continuas","s":"Uniforme, normal, exponencial, t, chi-cuadrado, F, beta, gamma y lognormal: qué mecanismo modela cada una y cómo se relacionan entre sí.","f":1},{"id":"distribuciones-discretas","t":"Distribuciones discretas","s":"Bernoulli, binomial, geométrica, Poisson y multinomial: qué mecanismo genera cada una y cómo elegir la correcta según lo que estés contando.","f":1},{"id":"distribuciones-en-datos-reales","t":"Distribuciones en datos reales","s":"Los datos reales casi nunca son normales: tienen colas gordas, dos picos, cortes por censura, ceros de más o son recuentos, y cada patrón pide otro estadístico.","f":5},{"id":"divide-y-venceras","t":"Divide y vencerás","s":"Partir el problema en subproblemas independientes del mismo tipo, resolverlos por separado y combinar; el teorema maestro dice cuánto cuesta.","f":10},{"id":"docker-para-datos","t":"Docker para datos","s":"Una imagen empaqueta tu código con sus librerías y sus versiones exactas, para que el mismo trabajo se ejecute igual en tu portátil y en el servidor.","f":4},{"id":"documentacion-tecnica","t":"Documentación técnica","s":"Documentación que no miente: un README que arranca el proyecto en un comando, decisiones registradas con su contexto y docstrings que respetan la firma.","f":12},{"id":"dropout-y-regularizacion","t":"Dropout y regularización","s":"Apagar neuronas al azar, encoger los pesos, parar a tiempo o inventar datos que no cambian la etiqueta: cuatro formas de encarecer la memorización.","f":7},{"id":"duckdb-y-analitica-local","t":"DuckDB y analítica local","s":"Un motor SQL analítico dentro de tu propio proceso: consulta Parquet y CSV de varios gigabytes sin servidor, sin clúster y sin cargarlo todo en memoria.","f":4},{"id":"economia-de-la-inferencia-propia","t":"Economía de la inferencia propia","s":"Pagar por token o alquilar la GPU son dos estructuras de coste distintas, y quien decide no es el precio de la hora sino la utilización real y el tamaño de los picos.","f":8},{"id":"ecuaciones-diferenciales-estocasticas","t":"Ecuaciones diferenciales estocásticas","s":"Cómo se escribe un modelo de precio como deriva más ruido, y cómo se simula sin que el paso temporal mienta sobre la incertidumbre.","f":9},{"id":"p-valor","t":"El p-valor","s":"La probabilidad de ver un resultado al menos tan extremo como el observado si la nula fuera cierta; no es la probabilidad de que la nula sea verdadera.","f":2},{"id":"problema-de-ficheros-pequenos","t":"El problema de los ficheros pequeños","s":"Miles de ficheros diminutos hunden un lago porque listar cuesta más que leer: compactación, tamaño objetivo y por qué particionar de más es un error.","f":4},{"id":"embeddings","t":"Embeddings","s":"Convertir palabras y categorías en vectores densos donde la distancia significa parecido: la base del texto, los recomendadores y la búsqueda semántica.","f":7},{"id":"enmascarado-y-retencion","t":"Enmascarado y retención","s":"Hash, tokenización y k-anonimato aplicados a un almacén real, y cómo se borra un dato a petición sin romper el histórico que ya calculaste.","f":4},{"id":"entorno-python","t":"Entorno de Python","s":"Un intérprete concreto más las versiones exactas de sus librerías: aislarlo por proyecto y fijarlas es lo que hace que tu análisis se pueda repetir.","f":3},{"id":"exactamente-una-vez","t":"Entrega exactamente una vez","s":"Reintentar da al menos una vez y no reintentar da como mucho una vez; exactamente una vez se consigue deduplicando el efecto en el punto irreversible.","f":11},{"id":"entrevistas-de-datos","t":"Entrevistas técnicas de datos","s":"Qué se mide de verdad en una entrevista de datos: acotar un problema ambiguo, escribir SQL sin duplicar filas y defender cada cifra con su base y su incertidumbre.","f":12},{"id":"entropia-e-informacion","t":"Entropía e información","s":"Entropía, entropía cruzada, divergencia KL e información mutua: la moneda con la que se mide la incertidumbre y se entrena casi todo el machine learning.","f":1},{"id":"fairness-y-equidad","t":"Equidad y métricas de fairness","s":"Paridad demográfica, igualdad de oportunidades y calibración por grupos: tres definiciones razonables de «justo» que no se pueden cumplir a la vez.","f":6},{"id":"errores-tipo-i-ii-y-potencia","t":"Errores tipo I y II, potencia","s":"Todo contraste falla de dos maneras: falsa alarma o incendio sin alarma; la potencia mide la segunda y se decide antes de recoger los datos.","f":2},{"id":"errores-y-depuracion","t":"Errores y depuración","s":"Un traceback se lee de abajo arriba: da el tipo de error y la línea exacta. try/except decide qué haces con él y el depurador te deja mirar las variables.","f":3},{"id":"escalado-y-transformacion","t":"Escalado y transformación","s":"Poner las variables en unidades comparables y acercar su forma a la normal: imprescindible en unos modelos, indiferente en otros y una fuente de fuga si se hace mal.","f":5},{"id":"escalares-vectores-matrices","t":"Escalares, vectores y matrices","s":"Un escalar es un número, un vector es una lista ordenada y una matriz es una tabla; casi todo dataset es una matriz y conviene saber qué eje es qué.","f":1},{"id":"escribir-tarjetas-de-repaso","t":"Escribir tarjetas de repaso","s":"Una tarjeta se escribe con una sola idea, con el contexto dentro del enunciado y con una respuesta que se pueda dar por buena o por mala sin discusión.","f":0},{"id":"escribir-un-informe","t":"Escribir un informe técnico","s":"Un informe técnico se lee en cinco minutos y de arriba abajo: conclusión primero, método reproducible, resultados con su incertidumbre, límites y qué hacer.","f":12},{"id":"especializacion-y-carrera","t":"Especialización y carrera","s":"Analista, analytics engineer, ingeniero de datos, científico, MLE y quant: qué produce cada rol, cómo se define por su interfaz y cómo se pasa de uno a otro.","f":12},{"id":"esquema-estrella-y-copo","t":"Esquema en estrella y copo de nieve","s":"La estrella deja las dimensiones planas y el copo de nieve las normaliza; la primera gana casi siempre en analítica, y aquí se ve por qué y cuándo no.","f":4},{"id":"estacionariedad","t":"Estacionariedad","s":"Media, varianza y autocovarianza que no dependen del momento en que miras la serie; el supuesto que casi todo modelo temporal da por hecho.","f":5},{"id":"estimacion-bayesiana-map","t":"Estimación bayesiana y MAP","s":"Priors, posteriors y MAP: cómo la creencia previa entra en la estimación y por qué la regularización L2 es un prior gaussiano.","f":2},{"id":"estimadores-y-propiedades","t":"Estimadores y sus propiedades","s":"Insesgado, consistente, eficiente y suficiente: lo que hace útil a un estimador y por qué el mejor no siempre es el insesgado.","f":2},{"id":"etica-profesional","t":"Ética profesional","s":"Decir «no» con argumentos, reportar el resultado incómodo y no vender humo: tres decisiones que se toman en la reunión, no en un código deontológico.","f":12},{"id":"triple-barrera","t":"Etiquetado por triple barrera","s":"Tres barreras (beneficio, pérdida y tiempo) deciden cuándo se cierra una operación y cuál es su etiqueta, sin usar información del futuro.","f":9},{"id":"etl-vs-elt","t":"ETL frente a ELT","s":"Transformar antes o después de cargar los datos: la misma tubería con las etapas en otro orden, y una decisión que marca dónde vive tu lógica de negocio.","f":4},{"id":"evaluacion-de-llms","t":"Evaluación de LLMs","s":"Como se mide si un sistema con modelos de lenguaje funciona: conjuntos de prueba propios, métricas automáticas, jueces que hay que validar y regresiones que no se cuelan.","f":8},{"id":"evaluacion-de-modelos-generativos","t":"Evaluar un modelo generativo","s":"Fidelidad frente a diversidad: por qué ninguna métrica sola dice si un modelo generativo es bueno, qué mide cada número y cómo evaluar sin engañarse.","f":7},{"id":"eventos-push-y-webhooks","t":"Eventos push y webhooks","s":"Cuando el origen empuja en vez de esperar a que lo consultes: cómo verificar la firma, por qué llegan duplicados y qué hace falta para no inundar la tabla.","f":4},{"id":"evolucion-de-esquema","t":"Evolución de esquema","s":"Cambiar el esquema de una tabla sin romper a quien la lee: qué operaciones son seguras, cuáles exigen coordinación y por qué renombrar es la peor de todas.","f":4},{"id":"expansion-karhunen-loeve","t":"Expansión de Karhunen-Loève","s":"La versión continua del PCA: descomponer un proceso aleatorio en funciones propias de su covarianza y simularlo con muy pocos términos.","f":1},{"id":"hurst-y-memoria","t":"Exponente de Hurst","s":"Mide cómo crece la dispersión de una serie con el horizonte: 0,5 es un paseo aleatorio, por encima hay persistencia y por debajo, reversión a la media.","f":9},{"id":"exportar-y-servir-modelos","t":"Exportar y servir modelos","s":"Pasar un modelo entrenado a algo que corre fuera de tu portátil: ONNX, TorchScript, torch.compile y por qué el exportado da números parecidos pero no idénticos.","f":7},{"id":"regex-y-limpieza-de-texto","t":"Expresiones regulares","s":"Patrones para validar, extraer y sustituir texto; por qué casi siempre «funciona», dónde está la trampa del anclaje y cuándo no hay que usar una expresión regular.","f":3},{"id":"factores-y-fama-french","t":"Factores y Fama-French","s":"Más allá del mercado: tamaño, valor, momentum y calidad explican parte de lo que el CAPM deja fuera y hunden el alpha de casi cualquier backtest.","f":9},{"id":"fastapi","t":"FastAPI","s":"Rutas, validación con Pydantic, inyección de dependencias y documentación automática: el marco para servir un modelo en Python.","f":11},{"id":"feature-store","t":"Feature store","s":"Un feature store garantiza que la variable que el modelo vio al entrenar es la misma que verá al predecir, con el valor que existía en ese instante y no con el de hoy.","f":4},{"id":"fechas-y-horas","t":"Fechas, horas y zonas horarias","s":"Un instante y una hora local no son lo mismo; datetime, timedelta, UTC y el horario de verano, que dos días al año rompe la cuenta de 24 horas.","f":3},{"id":"ficheros-y-encoding","t":"Ficheros y codificaciones","s":"El mismo dato cambia de significado según la codificación, el formato y el separador; aquí se aprende a no corromperlo ni a perderlo por el camino.","f":3},{"id":"bloom-filters","t":"Filtros de Bloom","s":"Una estructura de unos pocos bits por elemento que responde «seguro que no está» con certeza y «puede que esté» con una probabilidad que tú eliges.","f":10},{"id":"flink-y-procesamiento-de-eventos","t":"Flink y procesamiento de eventos","s":"Un motor que procesa evento a evento con estado y watermarks, en lugar de micro-lotes: qué gana, qué complica y cuándo no compensa.","f":4},{"id":"hacer-preguntas-buenas","t":"Formular buenas preguntas","s":"Una pregunta útil dice qué unidad cuenta, sobre quién, con qué métrica, contra qué se compara y qué harás según el resultado. Lo demás es curiosidad.","f":0},{"id":"frecuencia-y-agregacion-temporal","t":"Frecuencia, granularidad y agregación","s":"Bajar de frecuencia no es resumir: promediar borra los picos, sumar un nivel da un número sin sentido y un ratio mal agregado miente.","f":5},{"id":"freelance-y-consultoria","t":"Freelance y consultoría","s":"Presupuestar y cobrar por entregables: días facturables reales, colchón de horas, cláusula de cambios y criterios de aceptación por escrito.","f":12},{"id":"fuentes-y-canales","t":"Fuentes, canales y datos","s":"Dónde aprender cada fase, qué fuente sirve para qué y por qué seis activas bastan: el mapa de recursos con enlaces directos.","f":0},{"id":"fuga-de-datos","t":"Fuga de datos (data leakage)","s":"Información que el modelo ve al entrenar y no existirá al predecir: el error que hace que un modelo parezca perfecto en el portátil y falle el primer día en producción.","f":5},{"id":"funciones-de-activacion","t":"Funciones de activación","s":"Sigmoide, tanh, ReLU y GELU: por qué sin no linealidad una red de veinte capas equivale a una regresión lineal","f":7},{"id":"funciones-de-perdida","t":"Funciones de pérdida","s":"El número que el entrenamiento empuja hacia abajo en cada paso; elegir la pérdida es decidir qué error te importa y cuál puedes ignorar.","f":7},{"id":"funciones-y-modulos","t":"Funciones, módulos y paquetes","s":"Una función le pone nombre y argumentos a un cálculo; un módulo lo guarda en un fichero y un paquete agrupa módulos para reutilizarlos sin copiar.","f":3},{"id":"garch-volatilidad","t":"GARCH y volatilidad","s":"La varianza de hoy depende del shock de ayer y de la volatilidad de ayer; modelarla por separado es lo que permite medir el riesgo cuando cambia.","f":5},{"id":"generacion-de-senales","t":"Generación de señales","s":"De la idea económica a una regla medible: universo, horizonte, IC, giro y capacidad, en ese orden y antes de escribir la primera línea de backtest.","f":9},{"id":"gestion-de-memoria","t":"Gestión de memoria","s":"Como se reserva y se libera la memoria de un proceso, por qué el recolector no lo arregla todo y por qué un trabajo de Spark se queda sin memoria.","f":11},{"id":"gestores-de-contexto","t":"Gestores de contexto y liberación de recursos","s":"El bloque with garantiza que el recurso se suelte al salir, aunque el cuerpo falle a mitad, y evita que un proceso largo se quede sin descriptores ni conexiones.","f":3},{"id":"git-avanzado","t":"Git avanzado","s":"Rebase, bisect y reflog: reescribir la historia con criterio, encontrar el commit que rompió algo y recuperar trabajo que dabas por perdido.","f":11},{"id":"git-para-datos","t":"Git para datos","s":"Ramas, commits y conflictos aplicados a un proyecto de datos, y por qué los ficheros de datos en crudo no se versionan en git.","f":3},{"id":"gobierno-y-privacidad","t":"Gobierno y privacidad del dato","s":"Quien responde de cada dato, cuánto tiempo se guarda, con qué base jurídica y cómo se borra: gobierno y privacidad son diseño, no un trámite final.","f":4},{"id":"gpu-y-rendimiento","t":"GPU y rendimiento","s":"Por qué una GPU entrena redes y cómo aprovecharla de verdad: memoria, precisión mixta, acumulación de gradiente y los cuellos de botella que sí importan.","f":7},{"id":"gradient-boosting","t":"Gradient boosting","s":"Sumar árboles pequeños que corrigen el error del anterior: la receta que domina los datos tabulares y en la que cada pieza cuenta.","f":6},{"id":"grafos-computacionales-y-autograd","t":"Grafos computacionales y autograd","s":"Cada operación con tensores construye un grafo; backward lo recorre al revés con la regla de la cadena y deja la derivada de la pérdida en cada parámetro.","f":7},{"id":"grafos-representacion","t":"Grafos: representación","s":"Lista o matriz de adyacencia cambian el coste de casi todo algoritmo de grafos; elegir mal la estructura arruina un recorrido que estaba bien pensado.","f":10},{"id":"graphql-y-grpc","t":"GraphQL y gRPC","s":"Consultar por esquema frente a protocolos binarios: cuándo conviene cada uno y qué precio se paga por elegir mal.","f":11},{"id":"griegas-y-cobertura","t":"Griegas y cobertura","s":"Las derivadas del precio de una opción, y cómo se resuelve la cartera que deja la exposición a cero sin apostar a la dirección.","f":9},{"id":"idempotencia-en-apis","t":"Idempotencia en APIs","s":"Repetir una petición no debe repetir el efecto: claves de idempotencia, respuestas guardadas y los detalles que deciden si un reintento te salva o te duplica el cobro.","f":11},{"id":"idempotencia-y-reintentos","t":"Idempotencia y reintentos","s":"Una tarea idempotente se puede repetir sin duplicar ni corromper nada; es lo que convierte un reintento en una red de seguridad en vez de en un problema.","f":4},{"id":"iam-y-permisos-cloud","t":"Identidad y permisos en la nube","s":"Quién puede hacer qué sobre qué recurso: roles, políticas, mínimo privilegio y por qué el comodín de permisos es el fallo de seguridad más caro.","f":4},{"id":"importancia-de-variables","t":"Importancia de variables","s":"La importancia no es una propiedad de la variable sino del modelo y de las demás variables; impureza, permutación y reajuste miden cosas distintas.","f":6},{"id":"imputacion-de-datos","t":"Imputación de datos","s":"Rellenar los huecos con media, mediana, modelo o KNN cambia la distribución; casi siempre hay que dejar además una marca de que el dato faltaba.","f":5},{"id":"incidentes-y-postmortem","t":"Incidentes y postmortem","s":"Qué hacer cuando algo se rompe en producción: severidades, runbook, mitigar antes de diagnosticar y un postmortem sin culpa con acciones que se cierran.","f":11},{"id":"independencia-y-condicionamiento","t":"Independencia y condicionamiento","s":"Independencia, independencia condicional y la paradoja de Berkson: por qué dos variables sin relación pueden parecer asociadas al condicionar en una tercera.","f":1},{"id":"indicadores-tecnicos","t":"Indicadores técnicos","s":"Qué calcula de verdad cada indicador clásico, para qué sirve y por qué optimizar sus parámetros sobre el histórico es la forma más rápida de engañarte.","f":9},{"id":"indices-y-busqueda-en-texto","t":"Índices y búsqueda en texto","s":"Índice invertido, análisis de texto, TF-IDF y BM25: cómo un motor encuentra los documentos relevantes sin leerlos todos en cada consulta.","f":10},{"id":"iac-y-terraform","t":"Infraestructura como código","s":"Describir servidores, redes y permisos en ficheros versionados permite revisar los cambios como código, recrear el entorno entero y saber qué hay contratado.","f":4},{"id":"prompting","t":"Ingeniería de prompts","s":"Un prompt es el enunciado de la tarea: rol, contexto, ejemplos, formato y criterio de exito, y se mejora midiendo, no buscando palabras magicas.","f":8},{"id":"ingenieria-de-features","t":"Ingeniería de variables","s":"Construir variables que resumen lo que sabes del problema: cocientes, diferencias, ventanas pasadas y agregados por grupo, siempre mirando solo hacia atrás.","f":5},{"id":"ingesta-incremental-y-cdc","t":"Ingesta incremental y CDC","s":"Leer solo lo que ha cambiado en vez de copiar la tabla entera: tres formas de hacerlo y por qué la más fiable es leer el registro de transacciones.","f":4},{"id":"inicializacion-de-pesos","t":"Inicialización de pesos","s":"Los pesos se sortean al azar antes de entrenar y la escala de ese sorteo decide si la señal sobrevive a diez capas o se apaga por el camino.","f":7},{"id":"instruccion-y-alineamiento","t":"Instrucción y alineamiento","s":"Como se pasa de un modelo que solo continua texto a un asistente que obedece: ajuste sobre instrucciones, modelos de recompensa, RLHF y DPO.","f":8},{"id":"ci-cd","t":"Integración y despliegue continuos","s":"Automatizar pruebas, construcción y publicación para que integrar deje de ser un acontecimiento: qué corre en cada fase y qué se construye una sola vez.","f":11},{"id":"integrales","t":"Integrales","s":"Acumular áreas infinitesimales: la integral es la operación inversa de derivar y el motivo de que casi toda probabilidad se calcule integrando.","f":1},{"id":"interpretabilidad-shap","t":"Interpretabilidad y SHAP","s":"Que parte de una predicción concreta se atribuye a cada variable: valores de Shapley, curvas PDP e ICE y los límites de todo ello.","f":6},{"id":"intervalos-de-confianza","t":"Intervalos de confianza","s":"El 95 % no es la probabilidad de que el parámetro caiga dentro: es la frecuencia con la que el procedimiento acierta si lo repites muchas veces.","f":2},{"id":"jacobiano-y-hessiano","t":"Jacobiano y Hessiano","s":"El jacobiano agrupa las derivadas de una función vectorial y el hessiano las segundas derivadas: la curvatura que dice si un punto crítico es mínimo, maximo o silla.","f":1},{"id":"arreglos-de-cache-y-lineas-de-cache","t":"Jerarquía de memoria y localidad de caché","s":"Por qué dos programas con las mismas operaciones tardan mil veces distinto: la distancia entre el dato y el núcleo decide el tiempo, no el número de operaciones.","f":10},{"id":"json-y-datos-anidados","t":"JSON y datos anidados","s":"JSON guarda objetos y listas unas dentro de otras; leerlo es fácil, pero convertirlo en tabla obliga a aplanar y a decidir cuántas filas salen.","f":3},{"id":"knn","t":"K vecinos más cercanos","s":"Guardar los datos y decidir por mayoría entre los k vecinos más parecidos: el modelo más simple que existe y el que peor envejece al crecer la dimensión.","f":6},{"id":"purged-kfold","t":"K-fold con purga y embargo","s":"Validación cruzada adaptada a etiquetas que solapan en el tiempo: quita del entrenamiento todo lo que toca al conjunto de prueba y deja un margen de embargo.","f":9},{"id":"k-means","t":"K-means","s":"Agrupar puntos alrededor de k centroides minimizando la suma de distancias al cuadrado, con el método del codo para elegir k y sus límites bien claros.","f":6},{"id":"kafka-y-colas","t":"Kafka y colas de mensajes","s":"Un registro distribuido y ordenado por partición donde los productores escriben y cada consumidor lee a su ritmo; la pieza que desacopla dos sistemas.","f":4},{"id":"kubernetes-basico","t":"Kubernetes básico","s":"Describes cuántas copias de tu contenedor quieres y Kubernetes las mantiene vivas, repartidas y accesibles; el precio es un clúster que hay que operar.","f":4},{"id":"testing-piramide","t":"La pirámide de pruebas","s":"Muchas pruebas unitarias rápidas, algunas de integración y muy pocas de extremo a extremo: la proporción que mantiene la suite útil y a la vez soportable.","f":11},{"id":"lakehouse-y-table-formats","t":"Lakehouse y formatos de tabla","s":"Una capa de metadatos sobre Parquet que aporta transacciones, viaje en el tiempo y esquema evolutivo: Delta Lake, Iceberg y Hudi sobre el mismo lago.","f":4},{"id":"latencia-y-ejecucion","t":"Latencia y ejecución","s":"El tiempo entre decidir y que el mercado vea tu orden solo importa en relación con lo que dura tu ventaja; medirlo mal invalida el backtest entero.","f":9},{"id":"leer-documentacion-oficial","t":"Leer la documentación oficial","s":"La documentación oficial es el contrato de quien lo cumple: se lee buscando la firma exacta en la versión que tienes instalada, no de principio a fin como un libro.","f":0},{"id":"lema-de-ito","t":"Lema de Itô","s":"La regla de la cadena del cálculo estocástico: el término de segundo orden que aparece al derivar y que explica el menos sigma al cuadrado partido por dos.","f":9},{"id":"ley-de-los-grandes-numeros","t":"Ley de los grandes números","s":"Por qué la media muestral acaba pareciéndose al valor esperado, por qué tarda tanto en parecerse y por qué no significa que las rachas se compensen.","f":1},{"id":"order-book-y-spread","t":"Libro de órdenes y diferencial","s":"Bid, ask, profundidad y desequilibrio: como leer el libro de órdenes, que cuesta cruzarlo y que se puede y no se puede sacar de el como señal.","f":9},{"id":"limites-y-continuidad","t":"Límites y continuidad","s":"El límite describe a dónde se acerca una función sin necesidad de llegar; la continuidad exige además que el valor de la función esté ahí.","f":1},{"id":"logaritmos-y-escalas-logaritmicas","t":"Logaritmos y escalas logarítmicas","s":"Un logaritmo cuenta multiplicaciones en vez de sumas, y una escala logarítmica pone factores iguales a distancias iguales para que quepan órdenes muy distintos.","f":1},{"id":"maldicion-de-la-dimensionalidad","t":"Maldición de la dimensionalidad","s":"Al añadir dimensiones el espacio se vacía, las distancias se igualan y el vecino más cercano deja de serlo; qué hacer cuando tu modelo sufre esto.","f":6},{"id":"map-reduce","t":"MapReduce y cómputo distribuido","s":"El patrón map, shuffle y reduce que sostiene Spark y Hadoop, y la razón de que casi todo el coste esté en el shuffle y no en el cálculo.","f":10},{"id":"svm","t":"Máquinas de vectores de soporte","s":"Separar dos clases con el hiperplano que deja el mayor margen posible, usando solo los puntos fronterizos y un núcleo cuando la frontera no es recta.","f":6},{"id":"markowitz-y-frontera","t":"Markowitz y la frontera eficiente","s":"Para cada nivel de riesgo, la cartera con más rentabilidad esperada: la frontera eficiente, por qué es bonita en teoría y por qué se resiste en la práctica.","f":9},{"id":"matriz-de-confusion","t":"Matriz de confusión","s":"La tabla de cuatro casillas que cuenta aciertos y errores de un clasificador binario, y el punto de partida de casi toda métrica.","f":6},{"id":"maxima-verosimilitud","t":"Máxima verosimilitud (MLE)","s":"Elegir los parámetros que hacen más probables los datos observados; de ahí salen el MLE de una moneda y la pérdida de la regresión logística.","f":2},{"id":"mcp-y-servidores-de-herramientas","t":"MCP y servidores de herramientas","s":"El protocolo que convierte cada herramienta en un servidor reutilizable: un solo cliente habla con todos los servidores, en vez de uno distinto para cada pareja.","f":8},{"id":"atencion","t":"Mecanismos de atención","s":"En vez de comprimir toda la secuencia en un estado fijo, cada posición consulta a todas las demás y se queda con lo relevante: la idea que desbloqueó los transformers.","f":7},{"id":"medidas-de-centralidad","t":"Medidas de centralidad","s":"Media, mediana y moda resumen un conjunto de datos en un solo número, y cada una miente de una forma distinta.","f":1},{"id":"medidas-de-dispersion","t":"Medidas de dispersión","s":"Rango, IQR, varianza, desviación típica y coeficiente de variación miden cuánto se alejan los datos; sin ellos, una media no describe nada.","f":1},{"id":"medir-tu-progreso","t":"Medir tu progreso sin engañarte","s":"La media acumulada esconde los cambios: mide tu rendimiento por ventanas, compáralo contigo mismo y no conviertas la métrica en el objetivo.","f":0},{"id":"meta-labeling","t":"Meta-etiquetado","s":"Un primer modelo decide la dirección de la apuesta y un segundo decide si merece dinero y cuánto: separa el lado del tamaño y sube la precisión.","f":9},{"id":"inferencia-causal-metodos","t":"Métodos de inferencia causal","s":"Cuatro diseños para estimar efectos causales cuando no puedes aleatorizar, cada uno con su supuesto de identificación y su forma característica de fallar.","f":2},{"id":"metricas-de-clasificacion","t":"Métricas de clasificación","s":"Exactitud, precisión, exhaustividad, F1 y balanced accuracy: cuál elegir según lo que cueste cada tipo de error.","f":6},{"id":"metricas-de-clustering","t":"Métricas de clustering","s":"Sin etiquetas no hay exactitud que calcular, así que un agrupamiento se juzga por su geometría con silueta, Davies-Bouldin, Calinski-Harabasz, gap y DBCV.","f":6},{"id":"metricas-de-producto","t":"Métricas de producto","s":"Qué medir para saber si el producto mejora de verdad: métrica norte, guardarraíles, retención por cohortes y estado estacionario en vez de números que suben solos.","f":12},{"id":"metricas-de-ranking","t":"Métricas de ranking","s":"Precision@k, recall@k, MAP, MRR y NDCG: cómo se evalúa un sistema cuando lo que importa es el orden y solo se mira la parte de arriba.","f":6},{"id":"metricas-de-regresion","t":"Métricas de regresión","s":"MAE, MSE, RMSE, MAPE y R cuadrado: qué mide cada una, en qué unidades está y en qué casos engaña.","f":6},{"id":"metricas-de-riesgo","t":"Métricas de riesgo: panorama","s":"Que se mide cuando se mide el riesgo de una estrategia, qué pregunta responde cada familia de métricas y por qué todas se pueden manipular eligiendo la muestra.","f":9},{"id":"metricas-y-alertas","t":"Métricas, SLO y alertas","s":"SLI, SLO y presupuesto de error: alertar por lo que sufre el usuario y no por causas, con etiquetas de cardinalidad baja o el sistema de métricas se cae.","f":11},{"id":"gmm","t":"Mezclas gaussianas","s":"Cada punto pertenece a cada grupo con una probabilidad, y el algoritmo EM alterna asignar esas probabilidades y reajustar las gaussianas de cada grupo.","f":6},{"id":"microestructura-de-mercado","t":"Microestructura de mercado","s":"Como se casan las órdenes, quién asume el riesgo de inventario y por qué esa mecánica decide si tu estrategia es viable o solo bonita en papel.","f":9},{"id":"mlops-y-cicd-de-modelos","t":"MLOps y CI/CD de modelos","s":"Versionar código, datos, entorno y semilla; validar los datos antes de entrenar y promover un modelo solo si su mejora supera el ruido de la medición.","f":4},{"id":"data-vault","t":"Modelado Data Vault","s":"Hub, enlace y satélite: un modelado que solo inserta filas y que aguanta que los orígenes cambien sin reescribir el histórico.","f":4},{"id":"modelado-dimensional","t":"Modelado dimensional","s":"Organizar los datos analíticos en hechos y dimensiones alrededor de un grano claro: el modelo que entienden las herramientas de BI y que sobrevive a los años.","f":4},{"id":"modelos-de-difusion","t":"Modelos de difusión","s":"Un proceso fijo que destruye los datos con ruido y una red que aprende a deshacer un paso cada vez: generación estable a cambio de muestreo lento.","f":7},{"id":"glm-y-logistica","t":"Modelos lineales generalizados y regresión logística","s":"Cuando la respuesta no es continua: función de enlace, odds, logit y por qué la regresión logística es el GLM más usado del oficio.","f":6},{"id":"modelos-multimodales","t":"Modelos multimodales","s":"Cómo una imagen o un audio acaban siendo tokens dentro del mismo contexto que el texto, cuánto ocupan de verdad y por qué el presupuesto manda antes que la calidad.","f":8},{"id":"momentos-y-cumulantes","t":"Momentos y cumulantes","s":"Media, varianza, asimetría y curtosis como una sola familia de números, y los cumulantes que sí se suman al combinar variables independientes.","f":1},{"id":"momentum","t":"Momentum","s":"Comprar lo que sube funciona en la muestra y duele en la racha: momentum 12-1, por qué se salta el último mes y por qué sus caídas son tan violentas.","f":9},{"id":"heaps-y-prioridad","t":"Montículos y colas de prioridad","s":"Un montículo guarda el mínimo o el máximo en la raíz y lo mantiene ahí con dos operaciones de O(log n), sin llegar a ordenar el resto de los elementos.","f":10},{"id":"movimiento-browniano","t":"Movimiento browniano","s":"El paseo aleatorio en tiempo continuo que sostiene casi todo modelo de precio, y por qué su varianza crece con el tiempo.","f":9},{"id":"mql5-y-metatrader","t":"MQL5 y MetaTrader","s":"El entorno donde opera la mayoría del trading minorista: qué permite de verdad su probador de estrategias y qué te está ocultando mientras te enseña una curva preciosa.","f":9},{"id":"multiplicidad-y-fdr","t":"Multiplicidad y FDR","s":"Comparar cien métricas a la vez dispara los falsos positivos; Bonferroni controla el error en familia y Benjamini-Hochberg la proporción de falsos.","f":2},{"id":"naive-bayes","t":"Naive Bayes","s":"Clasificador probabilístico que supone que las variables son independientes dada la clase; el supuesto es falso y aun así gana en texto por rápido y por honesto.","f":6},{"id":"normalizacion-vs-desnormalizacion","t":"Normalización frente a desnormalización","s":"Repartir cada dato en un solo sitio para no contradecirte, o duplicarlo a propósito para leer más rápido: el compromiso que decide tu modelo.","f":4},{"id":"normalizacion-por-lotes","t":"Normalización por lotes","s":"Reescala las activaciones de cada capa a media cero y varianza uno dentro del lote, y deja que la red reaprenda con dos parámetros la escala que le convenga.","f":7},{"id":"norma-y-distancias","t":"Normas y distancias","s":"Una norma mide el tamaño de un vector y una distancia, la separación entre dos puntos; elegir L1, L2, L∞ o Mahalanobis decide qué significa «cerca».","f":1},{"id":"notacion-matematica","t":"Notación matemática","s":"Σ, Π, ∈, ∂, ∇ y E[…] no son un idioma aparte: cada símbolo es una abreviatura de una frase. Apréndelos y las fórmulas dejan de dar miedo.","f":0},{"id":"notebooks-vs-scripts","t":"Notebooks frente a scripts","s":"Cuándo usar un notebook y cuándo un script, por qué el estado oculto arruina la reproducibilidad y cómo saber si tu análisis se puede repetir.","f":3},{"id":"np-completitud","t":"NP-completitud","s":"La frontera entre lo que se puede resolver rápido y lo que solo se puede comprobar rápido, y por qué una reducción convierte un problema en otro.","f":10},{"id":"nubes-y-servicios-gestionados","t":"Nubes y servicios gestionados","s":"Alquilar computo, almacen y bases analiticas en vez de montarlos: que se delega, quien paga el tiempo ocioso y por qué el modelo de cobro decide la factura.","f":4},{"id":"numpy-fundamentos","t":"NumPy: fundamentos","s":"Un ndarray es memoria contigua con un tipo fijo para todos los elementos: la misma operación sobre un millón de números, sin recorrerlos uno a uno en Python.","f":3},{"id":"observabilidad-de-datos","t":"Observabilidad de datos","s":"Medir frescura, volumen, esquema y distribución contra la historia del propio dato detecta lo que ningún test escrito de antemano iba a encontrar.","f":4},{"id":"observabilidad-de-llms","t":"Observabilidad de una aplicación con LLM","s":"Qué grabar de cada consulta, en qué forma y para qué: sin trazas por paso ni tokens medidos, un sistema con LLM no se puede depurar ni presupuestar.","f":8},{"id":"oltp-vs-olap","t":"OLTP frente a OLAP","s":"La base que atiende a la aplicación y la que responde preguntas de negocio tienen formas opuestas; usar una para lo otro acaba en bloqueos y consultas eternas.","f":4},{"id":"operaciones-matriciales","t":"Operaciones con matrices","s":"Sumar, multiplicar y trasponer matrices tiene reglas propias; el producto no es elemento a elemento y el orden de los factores cambia el resultado.","f":1},{"id":"optimizacion-con-restricciones","t":"Optimización con restricciones","s":"Multiplicadores de Lagrange y condiciones KKT: como maximizar o minimizar cuando hay restricciones, y por qué la cartera de maximo Sharpe sale de ahi.","f":1},{"id":"optimizacion-matematica","t":"Optimización matemática","s":"Programación lineal, entera, descenso de gradiente y metaheurísticas: cómo elegir el método según la forma del problema y qué garantía da cada uno.","f":10},{"id":"optimizadores","t":"Optimizadores","s":"La regla que convierte el gradiente en un paso sobre los pesos; SGD, momento, RMSprop, Adam y AdamW hacen cosas distintas con la misma información.","f":7},{"id":"ordenacion-externa","t":"Ordenación externa","s":"Ordenar más datos de los que caben en memoria: trozos que sí quepan, ordenar cada uno y fusionarlos con un montículo de k vías eligiendo bien la k.","f":10},{"id":"orquestacion-y-dag","t":"Orquestación y DAG","s":"Un grafo dirigido sin ciclos que dice qué tarea depende de cuál, cuándo se ejecuta cada una y qué hacer cuando una falla a las tres de la mañana.","f":4},{"id":"pandas-agrupaciones-y-joins","t":"Pandas: agrupaciones y uniones","s":"Agrupar y unir resuelven casi toda la transformación de tablas; el resto es saber cuándo apply es la respuesta equivocada y por qué una clave duplicada infla los totales.","f":3},{"id":"pandas-fundamentos","t":"Pandas: fundamentos","s":"Un DataFrame es una tabla de columnas con tipo propio y un índice compartido; entender qué devuelve cada corchete evita la mitad de los errores diarios.","f":3},{"id":"paper-trading","t":"Paper trading","s":"Operar con precios reales y órdenes que no existen: sirve para aprender la mecánica de la plataforma, no para saber si la estrategia gana dinero.","f":9},{"id":"paradigmas-de-aprendizaje","t":"Paradigmas de aprendizaje","s":"Supervisado, no supervisado, semisupervisado, autosupervisado y por refuerzo: lo que cambia entre ellos es de dónde sale la señal que el modelo usa para aprender.","f":6},{"id":"parquet-avro-orc","t":"Parquet, Avro y ORC","s":"Columnar frente a orientado a fila: por qué Parquet lee solo lo que necesitas, dónde encaja Avro y qué aporta ORC, con el orden de las filas como verdadero truco.","f":4},{"id":"particionado-y-clustering","t":"Particionado y clustering","s":"Cortar la tabla por fecha o región para que cada consulta lea solo su trozo, elegir la cardinalidad correcta y ordenar las filas dentro del fichero.","f":4},{"id":"patrones-de-diseno","t":"Patrones de diseño","s":"Estrategia, fábrica, observador y repositorio: nombres cortos para problemas de diseño que ya se han resuelto mil veces, con sus consecuencias.","f":11},{"id":"pedir-ayuda-tecnica","t":"Pedir ayuda técnica y que te la den","s":"Una duda se responde cuando lleva un ejemplo mínimo que falla, lo que ya has probado, las versiones exactas y la diferencia entre lo que esperabas y lo que pasó.","f":0},{"id":"perceptron-y-mlp","t":"Perceptrón y perceptrón multicapa","s":"La neurona, el sesgo, las capas y el teorema que explica por qué una capa oculta ya resuelve lo que una recta no puede","f":7},{"id":"perfilado-de-datos","t":"Perfilado y EDA automático","s":"Describir una tabla desconocida con números -tipo real, nulos, cardinalidad, rangos y valores frecuentes- antes de escribir una sola transformación.","f":3},{"id":"sample-weights","t":"Pesos de muestra","s":"Con etiquetas que se solapan, varias observaciones cuentan la misma información: pesarlas por su unicidad evita que el modelo cuente el mismo tramo varias veces.","f":9},{"id":"pilas-y-colas","t":"Pilas, colas y deques","s":"Dos formas de guardar y sacar: la pila devuelve lo último que entró y la cola lo primero; con ellas se resuelven paréntesis, recorridos por niveles y planificadores.","f":10},{"id":"pipelines-de-ml","t":"Pipelines de machine learning","s":"Encadenar imputación, escalado y modelo en un solo objeto: la forma practica de que ninguna transformación se ajuste con datos de prueba","f":6},{"id":"poblacion-y-muestra","t":"Población y muestra","s":"La población es lo que quieres describir y la muestra lo que mides; de esa distancia nacen el error de muestreo y casi todos los sesgos.","f":2},{"id":"polars","t":"Polars","s":"API de expresiones, plan perezoso y ejecución en paralelo sobre memoria de Arrow: la alternativa a Pandas cuando la tabla deja de ser cómoda.","f":3},{"id":"portfolio-y-proyectos","t":"Portfolio y proyectos","s":"Dos o tres proyectos reproducibles donde se ve el problema, las decisiones y el resultado valen más que veinte certificados y que un notebook sin README.","f":12},{"id":"practicar-con-datos-reales","t":"Practicar con datos reales","s":"Los datasets de juguete vienen limpios y con el problema ya resuelto. Practica con datos sucios y de verdad, y termina el proyecto: eso es lo que se puede enseñar.","f":0},{"id":"precision-y-error-numerico","t":"Precisión y error numérico","s":"Los números con decimales no se guardan exactos, así que 0,1 + 0,2 no da 0,3. Por eso se compara con tolerancia, se acumula con cuidado y el dinero se lleva en Decimal.","f":1},{"id":"prediccion-con-incertidumbre","t":"Predicción con incertidumbre","s":"Un número suelto esconde la parte que más importa: dar un intervalo con la cobertura prometida en vez de un único valor.","f":5},{"id":"preentrenamiento-y-escalado","t":"Preentrenamiento y escalado","s":"Como se construye un corpus, que se optimiza durante el preentrenamiento y por qué el tamaño de un modelo se decide con leyes de escalado y no por intuición.","f":8},{"id":"presentaciones","t":"Presentar a audiencias distintas","s":"La misma conclusión contada a negocio y a técnicos: qué se enseña, qué se guarda para el anexo y cuánto material cabe en el tiempo que te han dado.","f":12},{"id":"prevision-a-varios-pasos","t":"Previsión a varios pasos","s":"Predecir doce meses no es repetir doce veces la predicción de uno; la recursiva, la directa y la multi-salida se equivocan de forma distinta en cada horizonte.","f":5},{"id":"principios-solid","t":"Principios SOLID","s":"Cinco reglas sobre dónde poner las fronteras del código para que añadir algo nuevo no obligue a repasar todo lo que ya funcionaba.","f":11},{"id":"priorizar-y-planificar","t":"Priorizar: qué se hace, qué se aplaza y qué se descarta","s":"Cómo decidir en qué se trabaja cuando todo parece urgente: coste del retraso entre tamaño, capacidad real, trabajo en curso limitado y qué se descarta por escrito.","f":12},{"id":"privacidad-y-datos-en-llms","t":"Privacidad de datos en LLMs","s":"Cada prompt es una transferencia de datos a un tercero: que sale, quién lo recibe, cuánto se guarda y que no debería salir nunca de casa.","f":8},{"id":"privacidad-y-gdpr","t":"Privacidad y RGPD","s":"Base legal, minimización, derechos del interesado y retención: cómo se recogen datos personales en una analítica sin construir un problema legal ni técnico.","f":11},{"id":"probabilidad-condicional","t":"Probabilidad condicional","s":"La probabilidad de A sabiendo que B ha ocurrido: reduce el espacio muestral al suceso conocido y reescala, y por eso cambia cualquier conclusión.","f":1},{"id":"procesamiento-de-texto-clasico","t":"Procesamiento de texto clásico","s":"Contar palabras y ponderarlas por lo raras que son sigue ganando en textos cortos, tabulares o con pocos datos; el truco está en saber qué se pierde al hacerlo.","f":6},{"id":"batch-vs-streaming","t":"Procesamiento por lotes y en flujo","s":"Procesar cada hora o procesar cada evento: la decisión se toma con la latencia que la decisión tolera, el coste y la complejidad, no con lo moderna que suene.","f":4},{"id":"producto-punto-y-similitud","t":"Producto punto y similitud","s":"El producto punto mide cuánto apuntan dos vectores en la misma dirección; normalizado da la similitud del coseno, la base de los embeddings.","f":1},{"id":"programacion-dinamica","t":"Programación dinámica","s":"Cuando la recursión repite los mismos subproblemas, guardar sus resultados convierte un coste exponencial en uno polinómico sin cambiar el razonamiento.","f":10},{"id":"pronosticos-de-referencia-y-mase","t":"Pronósticos de referencia y MASE","s":"El naive, el naive estacional y la deriva son el listón que hay que batir antes de creerse un modelo, y el MASE es la métrica que pone ese listón en 1.","f":5},{"id":"prophet-y-modelos-modernos","t":"Prophet y modelos modernos","s":"Prophet descompone la serie en tendencia, estacionalidad y festivos; N-BEATS apila bloques densos y DeepAR aprende de muchas series. Cuándo aportan.","f":5},{"id":"protocolo-fix","t":"Protocolo FIX","s":"El estándar de mensajería de órdenes entre bancos, brókers y bolsas: campos numerados, byte separador y una sesión con secuencias que hay que mantener en orden.","f":9},{"id":"pruebas-de-equivalencia-y-no-inferioridad","t":"Pruebas de equivalencia y no inferioridad","s":"Cómo demostrar que dos cosas son prácticamente iguales, en lugar de limitarse a no encontrar diferencias, y por qué «no significativo» no es «equivalente».","f":2},{"id":"prueba-de-fondeo","t":"Pruebas de fondeo","s":"Las reglas de una prueba de fondeo (objetivo, límite diario y drawdown máximo) convierten el trading en un problema de supervivencia donde manda el tamaño de posición.","f":9},{"id":"psicologia-del-trading","t":"Psicología del trading","s":"Por qué una racha de siete pérdidas no significa que el sistema esté roto: plan escrito, un tamaño que aguante y juzgar decisiones en vez de resultados.","f":9},{"id":"pytorch-fundamentos","t":"PyTorch: fundamentos","s":"Tensores que recuerdan cómo se calcularon, un módulo con sus parámetros, un cargador de lotes y un bucle de cinco pasos que se repite.","f":7},{"id":"q-learning-y-policy-gradient","t":"Q-learning y gradiente de política","s":"Las dos familias del refuerzo profundo: aprender el valor de cada accion y actuar con avaricia, o parametrizar la política y subir su retorno esperado con gradiente.","f":7},{"id":"quantconnect-y-lean","t":"QuantConnect y LEAN","s":"Una plataforma en la nube con datos incluidos y un motor de código abierto: el mismo algoritmo pasa de backtest a papel y a real sin reescribirlo.","f":9},{"id":"que-es-un-mercado","t":"Qué es un mercado","s":"Quien compra, quién vende, quién pone el precio y quién cobra: el mapa del mercado antes de tocar una estrategia.","f":9},{"id":"rag-arquitectura","t":"RAG: arquitectura","s":"Recuperar, aumentar y generar: el patron completo de RAG, sus seis etapas y los puntos donde se rompe la cadena antes de llegar al modelo.","f":8},{"id":"ratio-de-sharpe","t":"Ratio de Sharpe","s":"Exceso de rentabilidad por unidad de volatilidad asumida; la métrica más citada del trading y la más fácil de inflar sin querer.","f":9},{"id":"rebalanceo","t":"Rebalanceo","s":"Devolver la cartera a sus pesos objetivo, por calendario o por banda: cuánto cuesta de verdad y por qué es una decisión de riesgo y no de rentabilidad.","f":9},{"id":"reconciliacion-y-pruebas","t":"Reconciliación y pruebas de datos","s":"Cuadrar el origen con el destino, escribir pruebas que fallen solas y guardar los recuentos para saber si el dato de hoy se parece al de siempre.","f":4},{"id":"bfs-y-dfs","t":"Recorridos BFS y DFS","s":"Dos formas de visitar todos los vértices de un grafo; la primera explora por capas y da distancias, la segunda se hunde y descubre ciclos, caminos y componentes.","f":10},{"id":"recursion-y-backtracking","t":"Recursión y backtracking","s":"Una función que se llama a sí misma con un problema más pequeño, y la técnica de deshacer pasos para explorar todas las posibilidades sin repetir trabajo.","f":10},{"id":"cnn","t":"Redes convolucionales","s":"Deslizar el mismo filtro diminuto por toda la imagen y compartir los pesos permite ver bordes, texturas y objetos con muy pocos parámetros.","f":7},{"id":"gan","t":"Redes generativas adversarias","s":"Dos redes que compiten: una fabrica muestras y la otra intenta distinguirlas. El equilibrio existe en teoria y es fragil en la practica.","f":7},{"id":"gnn","t":"Redes sobre grafos","s":"Cada nodo se representa agregando información de sus vecinos, capa a capa: la estructura del grafo entra en el modelo en lugar de tratarse como columnas sueltas.","f":7},{"id":"refactorizacion","t":"Refactorización","s":"Cambiar la forma del código sin cambiar lo que hace: pasos pequeños, olores que dicen dónde mirar y una red de pruebas que lo hace seguro.","f":11},{"id":"reformar-tablas-ancho-y-largo","t":"Reformar tablas: ancho y largo","s":"melt, pivot y stack cambian de sitio la información sin sumar nada; es el paso obligatorio para convertir doce columnas de meses en una serie temporal.","f":3},{"id":"regimenes-de-mercado","t":"Regímenes de mercado","s":"Detectar el clima antes de elegir modelo o exposición, sabiendo que el estado no se observa, que la detección llega tarde y que el suavizado mira al futuro.","f":9},{"id":"registro-de-esquemas","t":"Registro de esquemas","s":"El contrato que productores y consumidores comparten en streaming, y por qué añadir un campo sin valor por defecto rompe a todos los que leen.","f":4},{"id":"logging-y-trazas","t":"Registro y trazas","s":"Registrar para poder depurar: niveles con contrato, mensajes estructurados, identificadores de correlación y trazas que enseñan dónde se fue el tiempo.","f":11},{"id":"registros-rechazados-y-cuarentena","t":"Registros rechazados, cuarentena y parada del pipeline","s":"Qué hacer con la fila que no cumple las reglas: apartarla con su motivo, reprocesarla después o parar el lote entero cuando la tasa de rechazo deja de ser ruido.","f":4},{"id":"regla-de-la-cadena","t":"Regla de la cadena","s":"Derivar una función compuesta es multiplicar las derivadas de sus piezas en orden, y eso es exactamente la retropropagación.","f":1},{"id":"reglas-de-asociacion","t":"Reglas de asociación","s":"Convertir millones de tickets en reglas del tipo «quien compra pan compra mantequilla», con el lift como único número que distingue un hallazgo de una obviedad.","f":6},{"id":"regresion-lineal","t":"Regresión lineal","s":"Ajustar la recta que minimiza la suma de errores al cuadrado, leer sus coeficientes con sentido y no confundirla con causalidad.","f":6},{"id":"regularizacion-l1-l2","t":"Regularización L1 y L2","s":"Ridge encoge los coeficientes y Lasso lleva algunos a cero: cómo la penalización cambia el equilibrio sesgo-varianza y cuándo usar cada una.","f":6},{"id":"rendimiento-y-perfilado","t":"Rendimiento y perfilado","s":"Medir antes de optimizar: dónde se va el tiempo, cuánta memoria ocupa cada objeto y qué cuello de botella atacar primero.","f":11},{"id":"reranking","t":"Reordenación","s":"Recuperar cien candidatos rápido y barato, y reordenarlos con un modelo que lee consulta y documento juntos: la forma más rentable de mejorar la recuperación.","f":8},{"id":"reproducibilidad-del-entrenamiento","t":"Reproducibilidad del entrenamiento","s":"Por qué dos ejecuciones con el mismo código no dan el mismo número, qué fuentes de azar hay que fijar y qué parte del determinismo no se puede recuperar.","f":7},{"id":"resiliencia-de-servicios","t":"Resiliencia de servicios: cortacircuitos y degradación","s":"Qué hacer cuando una dependencia se pone lenta: timeouts medidos, reintentos con espera creciente y azar, cortacircuitos, cupos y degradación en vez de caída total.","f":11},{"id":"retornos-logaritmicos","t":"Retornos logarítmicos","s":"Mide la variación proporcional de un precio, se suma en el tiempo y se anualiza sin trucos, por eso es la unidad de trabajo de casi todo modelo financiero.","f":9},{"id":"retropropagacion","t":"Retropropagación","s":"La regla de la cadena aplicada capa a capa, con el grafo computacional, los deltas y una comprobación numérica del gradiente","f":7},{"id":"reverse-etl","t":"Reverse ETL","s":"Devolver al CRM, al soporte y a los anuncios lo que el almacén ya sabe del cliente: escritura por clave, campos con un solo dueño y respeto a los límites de la API.","f":4},{"id":"reversion-a-la-media","t":"Reversión a la media","s":"Si una serie vuelve a su nivel habitual, cada desviación es una oportunidad; si pasea, cada desviación es el principio de la siguiente. Distinguirlo es todo.","f":9},{"id":"code-review","t":"Revisión de código","s":"Que mirar en una revisión, cómo comentar para que el cambio se haga y qué conviene delegar en la máquina antes de que un humano abra el diff.","f":11},{"id":"riesgo-de-ruina","t":"Riesgo de ruina","s":"La probabilidad de perder el capital, o de llegar a un nivel del que ya no puedes seguir, antes de que la ventaja de tu sistema tenga tiempo de imponerse.","f":9},{"id":"risk-parity-y-hrp","t":"Risk parity y HRP","s":"Repartir el riesgo en vez del capital: pesos de igual contribución y la jerarquía de correlaciones que estabiliza la cartera cuando la matriz estimada no es fiable.","f":9},{"id":"rnn-lstm-gru","t":"RNN, LSTM y GRU","s":"Una red que se pasa su propio estado de un paso al siguiente, y las puertas que añaden LSTM y GRU para que el gradiente no se desvanezca por el camino.","f":7},{"id":"rutas-de-aprendizaje","t":"Rutas de aprendizaje","s":"Las cuatro rutas completas —data engineer, data scientist, IA y quant— con el orden de cada paso y lo que hay que saber antes de empezar cada uno.","f":0},{"id":"structured-output","t":"Salida estructurada","s":"Pedir al modelo un objeto con campos y tipos, validarlo contra un esquema y reintentar con el error: por qué parsear texto libre con expresiones regulares acaba roto.","f":8},{"id":"scripts-ejecutables-y-argumentos","t":"Scripts ejecutables y argumentos","s":"De notebook a herramienta: leer los datos por argumentos con argparse, construir las rutas con pathlib y salir con código distinto de cero cuando algo falla.","f":3},{"id":"secretos-y-configuracion","t":"Secretos y configuración","s":"Que es un secreto, dónde se guarda, cómo se rota y por qué borrarlo en un commit posterior no lo borra de ninguna parte.","f":11},{"id":"seguimiento-de-experimentos","t":"Seguimiento de experimentos","s":"Qué guardar de cada ejecución para poder comparar dos configuraciones sin fiarte de la memoria, y cómo saber si una mejora es real o es ruido entre semillas.","f":7},{"id":"seguridad-owasp","t":"Seguridad de aplicaciones","s":"Las diez trampas que se repiten en cada aplicación: inyección, XSS, CSRF, control de acceso roto y dependencias abandonadas, con lo que hay que revisar siempre.","f":11},{"id":"seguridad-y-prompt-injection","t":"Seguridad e inyección de prompts","s":"El modelo no distingue instrucciones de datos, así que cualquier texto externo es un vector de ataque: la defensa está en los permisos, no en el prompt.","f":8},{"id":"seleccion-de-features","t":"Selección de variables","s":"Quedarse con las variables que aportan y tirar el resto: filtros, envolventes y métodos embebidos, con la estabilidad como criterio y sin colar el futuro.","f":5},{"id":"series-jerarquicas","t":"Series jerárquicas y reconciliación","s":"Predecir por separado el total, las tiendas y los productos da cifras que no suman; la reconciliación reparte el desajuste.","f":5},{"id":"series-temporales-en-pandas","t":"Series temporales en Pandas","s":"Con la fecha en el índice, Pandas agrega por ventanas, calcula medias móviles por tiempo, desplaza y une series de frecuencias distintas por el instante más cercano.","f":3},{"id":"motores-de-inferencia-para-llms","t":"Servir un LLM en abierto: motores y cuantización","s":"Generar un token está limitado por el ancho de banda de memoria, no por los FLOPs: de ahí salen la cuantización, el lote continuo y la caché de claves.","f":8},{"id":"sesgo-de-mirar-al-futuro","t":"Sesgo de mirar al futuro","s":"Usar en la decisión de hoy información que solo existía después: el error que convierte cualquier backtest en una máquina de imprimir dinero.","f":9},{"id":"sesgo-de-supervivencia","t":"Sesgo de supervivencia","s":"Analizar solo los fondos, acciones o exchanges que siguen vivos y tomar ese grupo como si fuera el mercado entero: la media que sale nunca existió.","f":9},{"id":"sesgo-y-etica-en-datos","t":"Sesgo y ética en datos","s":"Un modelo aprende lo que hay en los datos, incluidas las injusticias que ya existían: como detectar sesgo, que mide cada métrica y por qué no se cumplen todas.","f":11},{"id":"sesgo-varianza-mse","t":"Sesgo, varianza y ECM","s":"El error que puedes esperar se descompone en ruido irreducible, sesgo al cuadrado y varianza; por eso un modelo algo sesgado puede predecir mejor.","f":2},{"id":"sharpe-deflactado","t":"Sharpe deflactado","s":"Ajusta el Sharpe observado por el número de intentos y por la forma de la distribución: la probabilidad de que no sea el mejor resultado del ruido.","f":9},{"id":"simulacion-de-monte-carlo","t":"Simulación de Monte Carlo","s":"En vez de mirar la única curva que te dio el backtest, generas miles de curvas alternativas a partir de tus resultados y miras el abanico completo.","f":9},{"id":"recomendadores","t":"Sistemas de recomendación","s":"Filtrado colaborativo, basado en contenido y factorización de matrices, con la parte que casi nadie hace bien: evaluar el orden de la lista, no el error de la nota.","f":6},{"id":"sistemas-distribuidos-bases","t":"Sistemas distribuidos: bases","s":"Que cambia cuando el sistema vive en varias máquinas: particiones, réplicas, relojes que no coinciden y fallos que solo afectan a una parte.","f":11},{"id":"sobreajuste-en-redes","t":"Sobreajuste en redes","s":"Aprender a leer las dos curvas de un entrenamiento para detectar sobreajuste y decidir en que orden tocar datos, regularización y capacidad.","f":7},{"id":"sortino-y-calmar","t":"Sortino y Calmar","s":"Dos correcciones al ratio de Sharpe: penalizar solo la volatilidad que duele y medir la rentabilidad contra la peor caída que has sufrido.","f":9},{"id":"spark-fundamentos","t":"Spark: fundamentos","s":"Un motor distribuido con evaluación perezosa: qué es un RDD, qué añade el DataFrame y por qué no es «Pandas en grande».","f":4},{"id":"spark-particiones-y-shuffle","t":"Spark: particiones y shuffle","s":"El shuffle reescribe y reordena todos los datos entre ejecutores; es la operación más cara de Spark y decide si un trabajo tarda minutos u horas.","f":4},{"id":"spark-joins-y-skew","t":"Spark: uniones y asimetría","s":"Unir tablas reparte claves entre tareas; cuando una clave concentra media tabla, esa tarea decide cuánto tarda el trabajo y hay que repartirla.","f":4},{"id":"sql-agregaciones-y-group-by","t":"SQL: agregaciones y GROUP BY","s":"Partir la tabla en montones que comparten una clave y resumir cada montón en una fila; donde va cada filtro y por qué los nulos cambian la media.","f":3},{"id":"sql-select-y-filtros","t":"SQL: consultas y filtros","s":"SELECT, WHERE, ORDER BY y LIMIT con su orden de evaluación real, la lógica de tres valores de NULL y lo que cambia entre dialectos.","f":3},{"id":"sql-ventanas","t":"SQL: funciones de ventana","s":"Calcular un valor por fila mirando sus vecinas -ranking, diferencias, acumulados y medias móviles- sin colapsar la tabla como hace GROUP BY.","f":3},{"id":"sql-indices-y-planes","t":"SQL: índices y planes","s":"Por qué una consulta que devuelve 20 filas tarda un minuto: qué hace un índice, cuándo el motor lo ignora y cómo leer el plan de ejecución.","f":3},{"id":"sql-modelado-y-normalizacion","t":"SQL: modelado y normalización","s":"Que entidades existen, con qué clave se identifican y en qué tabla vive cada hecho; por qué repetir la ciudad del cliente en cada pedido acaba rompiendo los informes.","f":3},{"id":"sql-subconsultas-y-cte","t":"SQL: subconsultas y CTE","s":"Consultas dentro de consultas y el WITH que les pone nombre; cómo se lee una consulta larga de arriba abajo sin perderse por el camino.","f":3},{"id":"sql-joins","t":"SQL: uniones","s":"INNER, LEFT, FULL y CROSS, autocombinaciones y el error clásico de duplicar filas al unir antes de agregar.","f":3},{"id":"stacking-y-blending","t":"Stacking y blending","s":"Combinar varios modelos con un metamodelo entrenado sobre predicciones fuera de muestra; la diferencia entre ganar y sobreajustar está en cómo se generan esas predicciones.","f":6},{"id":"streaming-tiempo-real","t":"Streaming: ventanas y marcas de agua","s":"Cuándo ocurrió un evento no es cuándo llegó: ventanas, marcas de agua, tolerancia a tardanzas y la letra pequeña de exactamente una vez.","f":4},{"id":"suavizado-exponencial","t":"Suavizado exponencial","s":"Media ponderada en la que lo reciente pesa más, con variantes para tendencia y estacionalidad; el pronóstico barato que cuesta batir.","f":5},{"id":"supuestos-de-la-regresion","t":"Supuestos de la regresión","s":"Linealidad, independencia, homocedasticidad y normalidad: qué rompe cada supuesto, qué sigue funcionando y cómo se diagnostica.","f":6},{"id":"tsne-y-umap","t":"t-SNE y UMAP","s":"Dos formas de dibujar datos de muchas dimensiones en un plano que conservan los vecindarios y se inventan el resto: sirven para mirar, no para medir.","f":6},{"id":"hechos-y-dimensiones","t":"Tablas de hechos y dimensiones","s":"La tabla de hechos guarda lo que se mide y las dimensiones lo que describe; las claves sustitutas y el grano son lo que impide que las sumas cuenten doble.","f":4},{"id":"tablas-hash","t":"Tablas hash","s":"Convierten una clave en una posición de un array para responder en O(1) de media, a cambio de aceptar colisiones y vigilar el factor de carga.","f":10},{"id":"tamano-de-posicion","t":"Tamaño de posición","s":"Cuantas unidades abres por idea: riesgo fijo, volatilidad objetivo y límites por correlación, la decisión que convierte una señal en resultados.","f":9},{"id":"tamano-del-efecto","t":"Tamaño del efecto","s":"Cuanto de grande es una diferencia, en una unidad que no depende de cuántos datos tengas; la d de Cohen y la diferencia relativa.","f":2},{"id":"tasas-de-aprendizaje-y-schedulers","t":"Tasa de aprendizaje y planificadores","s":"El hiperparámetro que más cambia el resultado, y cómo moverlo durante el entrenamiento con calentamiento, escalones o coseno.","f":7},{"id":"teorema-central-del-limite","t":"Teorema central del límite","s":"Por qué la media de casi cualquier cosa se distribuye como una normal, de dónde sale el error típico y cuándo la aproximación deja de servir.","f":1},{"id":"teorema-de-bayes","t":"Teorema de Bayes","s":"Como dar la vuelta a una probabilidad condicional: la regla que convierte la tasa de acierto de un test en la probabilidad real de estar enfermo.","f":1},{"id":"terminal-y-shell","t":"Terminal y shell","s":"Pipes, permisos, códigos de salida y cron: la herramienta con la que se depura un pipeline cuando algo falla a las tres de la mañana.","f":3},{"id":"chi-cuadrado","t":"Test chi-cuadrado","s":"Contrastar si dos variables categóricas se relacionan o si unas frecuencias observadas encajan con las esperadas, y medir cuánto.","f":2},{"id":"test-t","t":"Test t","s":"Comparar una media con un valor de referencia o dos medias entre sí, eligiendo bien la variante y respetando los supuestos.","f":2},{"id":"ab-testing","t":"Tests A/B","s":"Un experimento aleatorizado con métrica decidida de antemano, duración calculada y reglas de parada fijadas antes de mirar los datos.","f":2},{"id":"testing-con-pytest","t":"Tests con pytest","s":"Fixtures, parametrización y cobertura: qué merece un test en un pipeline de datos y qué es una pérdida de tiempo disfrazada de rigor.","f":3},{"id":"remuestreo-y-permutacion","t":"Tests de permutación","s":"Construir la distribución nula barajando las etiquetas del propio experimento: un contraste exacto, sin supuestos de distribución y válido para casi cualquier estadístico.","f":2},{"id":"test-adf-kpss","t":"Tests de raíz unitaria: ADF y KPSS","s":"Dos contrastes con hipótesis nulas opuestas para decidir si una serie necesita diferenciarse, y por qué hay que usarlos juntos.","f":5},{"id":"tests-no-parametricos","t":"Tests no paramétricos","s":"Mann-Whitney, Wilcoxon, Kruskal-Wallis y Kolmogorov-Smirnov: contrastar sin suponer una forma concreta para la distribución.","f":2},{"id":"tipado-y-linters","t":"Tipado y linters","s":"Anotaciones de tipo, dataclasses y Pydantic: cómo detectar antes de ejecutar los errores que en un pipeline de datos cuestan una tarde de depuración.","f":3},{"id":"tipos-y-estructuras-python","t":"Tipos y estructuras de Python","s":"Listas, tuplas, diccionarios y conjuntos guardan varios valores; elegir mal no rompe el programa, lo hace lento o lo llena de errores silenciosos.","f":3},{"id":"tokenizacion","t":"Tokenización","s":"Partir el texto en unidades antes de convertirlo en vectores: BPE, WordPiece y por qué los números, los acentos y las palabras raras se fragmentan de más.","f":7},{"id":"tomar-notas-tecnicas","t":"Tomar notas técnicas","s":"Una nota técnica es un mensaje a tu yo de dentro de seis meses: qué pasaba, qué decidiste, por qué y con qué versiones, en texto plano que se pueda buscar.","f":0},{"id":"pairs-trading","t":"Trading de pares","s":"Dos activos, un diferencial y un z-score: cómo elegir el par, estimar el ratio de cobertura y decidir la salida sin engañarte con la muestra.","f":9},{"id":"transacciones-y-bloqueos","t":"Transacciones, aislamiento y bloqueos","s":"Agrupa varias escrituras en una unidad que se aplica entera o no se aplica, y decide qué ve la otra sesión mientras tanto para que dos procesos no se pisen el trabajo.","f":3},{"id":"transformaciones-lineales","t":"Transformaciones lineales","s":"Una matriz es una acción sobre el espacio: rota, escala, proyecta o refleja, y sus columnas son las imágenes de los vectores de la base.","f":1},{"id":"transformers","t":"Transformers","s":"Autoatención multi-cabeza, sin recurrencia y en paralelo: el bloque que compone casi todos los modelos de lenguaje actuales, con su coste y sus límites.","f":7},{"id":"chunking-y-embeddings","t":"Troceado y embeddings","s":"Como se corta el texto antes de vectorizarlo: tamaño de fragmento, solapamiento y por qué la frontera elegida decide lo que el buscador no encontrará.","f":8},{"id":"umbrales-y-coste","t":"Umbrales y coste del error","s":"El 0,5 es una convención, no una decisión: el punto de corte correcto sale del coste real de cada falso positivo y cada falso negativo.","f":6},{"id":"uplift-y-valor-incremental","t":"Uplift y valor incremental","s":"El efecto de intervenir frente a no hacerlo, medido sobre quien de verdad cambia de comportamiento y no sobre quien ya iba a comprar.","f":6},{"id":"usar-ia-para-aprender","t":"Usar la IA para aprender sin engañarte","s":"Un modelo puede ser tu tutor o tu atajo, y solo se distinguen al defender el resultado: pide explicaciones, comprueba cada afirmación y no pegues código que no entiendas.","f":0},{"id":"validacion-combinatoria-cpcv","t":"Validación combinatoria (CPCV)","s":"Reparte el histórico en bloques y prueba todas las combinaciones posibles: obtienes la distribución de resultados de la estrategia en vez de un único número.","f":9},{"id":"validacion-cruzada","t":"Validación cruzada","s":"Partir los datos en k pliegues para estimar y elegir sin gastar un conjunto de prueba, con variantes para clases raras, grupos y series temporales.","f":6},{"id":"validacion-temporal","t":"Validación temporal","s":"Por qué el K-fold barajado miente con datos ordenados en el tiempo y cómo se evalúa de verdad, con ventanas hacia delante y sin fuga de información.","f":5},{"id":"valor-esperado","t":"Valor esperado","s":"La media teórica de una variable aleatoria, por qué se suma tan fácilmente y por qué E[X·Y] no es E[X]·E[Y] salvo que sean independientes.","f":1},{"id":"valoracion-de-opciones","t":"Valoración de opciones","s":"Por qué una opción tiene un precio único aunque nadie sepa a dónde va el activo: replicación, medida neutral al riesgo y la fórmula de Black-Scholes.","f":9},{"id":"outliers-y-deteccion","t":"Valores atípicos","s":"Detectar un valor que se aleja del resto es fácil; decidir si es un error de medición, un dato mal tecleado o el fenómeno que buscas es el trabajo que de verdad importa.","f":5},{"id":"var-y-cvar","t":"VaR y CVaR","s":"El VaR pone el umbral de pérdida que no se supera con cierta probabilidad y el CVaR mide la pérdida media cuando ese umbral se rompe.","f":9},{"id":"variable-aleatoria","t":"Variable aleatoria","s":"Una función que asigna un número a cada resultado de un experimento, con su masa o densidad y su función de distribución asociadas.","f":1},{"id":"varianza-y-desviacion","t":"Varianza y desviación típica","s":"Cuanto se aleja una variable de su media, por qué se mide en unidades al cuadrado y cómo se combinan las varianzas al sumar variables.","f":1},{"id":"vectorbt-backtrader-zipline","t":"VectorBT, Backtrader y Zipline","s":"Las tres librerías de backtesting que más se usan en Python, qué modelo del mundo tiene cada una y para qué sirve cada modelo.","f":9},{"id":"vectorizacion","t":"Vectorización","s":"Sustituir los bucles por operaciones sobre el array entero: máscaras booleanas, where y agregaciones por grupo, sin recorrer fila a fila en Python.","f":3},{"id":"venta-en-corto-mecanica","t":"Vender en corto: préstamo, coste y recalls","s":"Vender algo que no tienes tiene fecha de caducidad y precio: quién te lo presta, cuánto cobra por ello y qué pasa cuando te lo reclama.","f":9},{"id":"ventanas-de-contexto","t":"Ventana de contexto","s":"Cuantos tokens caben a la vez, por qué lo del medio se olvida y como trocear y ordenar la información para que el modelo la use de verdad.","f":8},{"id":"ventanas-y-watermarks","t":"Ventanas y marcas de agua","s":"Cuándo cerrar una ventana de agregación, cuánto esperar a los datos que llegan tarde y qué hacer con los que aparecen después del cierre.","f":4},{"id":"vistas-y-copias","t":"Vistas, copias y aliasing","s":"Una rebanada no copia nada: comparte memoria con el original. Distinguir vista de copia evita el bug más silencioso y más caro de los datos.","f":3},{"id":"visualizacion-matplotlib","t":"Visualización con Matplotlib","s":"Figuras, ejes, escalas y anotaciones con Matplotlib, y las decisiones de ejes que hacen que un gráfico mienta sin querer.","f":3},{"id":"visualizacion-estadistica","t":"Visualización estadística","s":"Boxplots, violines, densidades y matrices de correlación: cómo enseñar una distribución entera en vez de un solo número que la esconde.","f":3},{"id":"visualizacion-honesta","t":"Visualización honesta","s":"Un gráfico puede decir la verdad y mentir a la vez: ejes truncados, escalas mal elegidas, agregaciones que invierten la conclusión y colores que engañan sin querer.","f":12},{"id":"volatilidad-realizada","t":"Volatilidad realizada","s":"La raíz de la suma de los retornos intradía al cuadrado mide cuánto se movió el precio de verdad, y es la variable de entrada de casi todo modelo de volatilidad.","f":9},{"id":"volatility-drag","t":"Volatility drag","s":"Por qué dos carteras con la misma media acaban en sitios distintos, y cómo la volatilidad se come el interés compuesto aunque el activo no baje.","f":9},{"id":"scraping-etico","t":"Web scraping responsable","s":"Antes de rascar una web hay que leer robots.txt, limitar el ritmo, cachear lo descargado y comprobar si existe una API o un fichero que ya lo ofrece.","f":3},{"id":"xgboost-lightgbm-catboost","t":"XGBoost, LightGBM y CatBoost","s":"Los tres motores de boosting que dominan los datos tabulares: en qué se diferencian al crecer los árboles y cuándo conviene elegir cada uno.","f":6},{"id":"z-score-y-estandarizacion","t":"Z-score y estandarización","s":"El z-score dice a cuántas desviaciones típicas está un valor de la media; sirve para comparar escalas distintas y para detectar valores atípicos.","f":1}];
